-- Forward-only reconciliation of the post-release Kurmanji lesson payloads.
-- Historical release migration 20261024122051 remains unchanged and immutable.
-- Source of truth: the five split seed files, including the documented Avasin
-- Sorani house style. Only the 12 rows that drifted after the release are updated.
-- This migration refuses to overwrite any row that no longer matches the exact
-- historical release payload; inspect and reconcile such drift manually first.

BEGIN;

DO $preflight$
DECLARE
  matched_rows integer;
BEGIN
  PERFORM 1
  FROM public.lesson_content AS actual
  JOIN (
    VALUES
    ('kurmanji-course-1-lesson-01.html', 'kurmanji-course-1', 'ناسینی کورمانجی و چوارچێوەی ڕێنووسی لاتینی', '<section class="klesson-card"><h2>١. کورمانجی چیە؟</h2><p>کورمانجی (Kurmancî) یەکێکە لە شێوە و ڕێڕەوە زمانیە سەرەکییەکانی کوردی. لە زۆرێک لە بەکارهێنانە نوسراوە هاوچەرخەکاندا، کورمانجی بە ئەلفبێی لاتینیی هاوار دەنووسرێت. ئەم وانەیە ئەم سیستەمەی نوسین دەکاتە بابەتی سەرەکی؛ بەڵام نابێت ئەلفبێی نوسین لە خودی زمان یان لە هەمو تایبەتمەندییە دەنگییەکانی جیاوازییە زمانیەکان یەکسان بگیرێت.</p></section>
<section class="klesson-card"><h2>٢. جیاوازیی زمان، ئەلفبێ و ڕێنووس</h2><ul><li><strong>زمان:</strong> سیستەمی گشتیی پەیوەندی و ڕێکخستنی زمانیە.</li><li><strong>ئەلفبێ:</strong> کۆمەڵە نیشانەی نوسینە کە بۆ نوسینی زمان بەکاردێن.</li><li><strong>ڕێنووس:</strong> ڕێساکانی نوسینی وشە و بەکارهێنانی نیشانەکانی نوسینە.</li></ul><p>لە فێربونی کورمانجی‌دا، ناسینی پیتەکان پێشەنگییەکی گرنگە؛ بەڵام تەنیا زانینی ناوی پیتەکان بەس نیە. فێرخواز دەبێت فۆڕمی نووسراو، خوێندنەوەی باو و شوێنی پیتەکان لە وشەدا بە یەکەوە فێرببێت.</p></section>
<section class="klesson-card"><h2>٣. سنووری ڕێڕەوی ئەم کۆرسە</h2><p>کۆرسی یەکەم لە ٢٦ وانەدا لە ناساندنی سیستەمی نوسینەوە دەگاتە خوێندنەوە و نوسینی وشە و ڕستەی سادە. بابەتەکانی مۆرفۆلۆجی و ڕێزمان بە شێوەیەکی ڕێک‌خراوتر لە کۆرسی دووەمدا دەخوێندرێنەوە.</p><div class="klesson-note">تێبینیی زانستی: کورمانجی لە ناوچە و کۆمەڵگە جیاوازەکاندا هەندێک جیاوازیی دەربڕین و بەکارهێنانی هەیە. لە وانەکانی داهاتوودا نمونەکان بە پشت‌بەستن بە سەرچاوەی دیاریکراو دەخرێنەڕوو؛ نابێت شێوەیەکی تایبەت بە هەمو بەکارهێنانەکان بگشتێندرێت.</div></section>
<section class="klesson-card"><h2>٤. پێداچوونەوە</h2><ol><li>جیاوازی نێوان ئەلفبێ و ڕێنووس چیە؟</li><li>بۆچی پەیویستە سیستەمی نوسین لە خودی زمان جیا بکرێتەوە؟</li><li>ئەم کۆرسە چی دەگرێتەوە و بابەتە وردترەکانی ڕێزمان لە کوێ دەخوێندرێنەوە؟</li></ol></section>
<section class="klesson-card"><h2>سەرچاوەکان</h2><ol><li>Haig, Geoffrey. (2018). “Northern Kurdish (Kurmanjî).” In Geoffrey Haig & Geoffrey Khan (eds.), <em>The Languages and Linguistics of Western Asia: An Areal Perspective</em>, pp. 106–158. Berlin: De Gruyter Mouton. <a href="https://doi.org/10.1515/9783110421682-004" target="_blank" rel="noopener">DOI: 10.1515/9783110421682-004</a>.</li><li>Thackston, W. M. (2006). <em>Kurmanji Kurdish: A Reference Grammar with Selected Readings</em>. سەرچاوەی ڕێزمان و خوێندنەوەی کورمانجی.</li></ol><p class="klesson-note">ئەم دوو سەرچاوەیە بۆ چوارچێوەی گشتیی بابەتەکە دانراون؛ ژمارەی لاپەڕە نەنوسراوە، چونکە لەم قۆناغەدا پشتڕاست نەکراوەتەوە. پێش بڵاوکردنەوەی گشتی، زانیاریی تەواوی چاپ و بەش/لاپەڕەی پەیوەندیدار دەبێت لە خودی سەرچاوەکاندا بپشکنرێت.</p></section>'),
    ('kurmanji-course-1-lesson-02.html', 'kurmanji-course-1', 'ئەلفبێی هاوار و ٣١ پیتەکەی', '<section class="klesson-card"><h2>١. ڕیزبەندی ئەلفبێ</h2><p>لە ڕێنووسی لاتینیی باوی کورمانجی، ئەلفبێکە ٣١ پیت لەخۆ دەگرێت. ئەم ڕیزبەندییە بۆ ناسینەوە و ڕێکخستنی وشەکان گرنگە:</p><div class="klesson-alphabet" aria-label="ئەلفبێی کورمانجی"><span>A</span><span>B</span><span>C</span><span>Ç</span><span>D</span><span>E</span><span>Ê</span><span>F</span><span>G</span><span>H</span><span>I</span><span>Î</span><span>J</span><span>K</span><span>L</span><span>M</span><span>N</span><span>O</span><span>P</span><span>Q</span><span>R</span><span>S</span><span>Ş</span><span>T</span><span>U</span><span>Û</span><span>V</span><span>W</span><span>X</span><span>Y</span><span>Z</span></div><p class="klesson-note">تێبینی: پیتەکانی ئەم ئەلفبێیە بە ڕێنووسی لاتینیی کورمانجی پەیوەستن. نابێت نیشانەی پیتەکان لە نوسینی کوردی بە ئەلفبێی عەرەبی یان لە سیستەمەکانی دیکەدا بە هەمان شێوە لێک بدرێنەوە.</p></section>
<section class="klesson-card"><h2>٢. پیتەکانی نیشانەدار</h2><ul><li><strong>Ç / ç</strong></li><li><strong>Ê / ê</strong></li><li><strong>Î / î</strong></li><li><strong>Ş / ş</strong></li><li><strong>Û / û</strong></li></ul><p>ئەم نیشانانە بەشێکن لە شێوەی نوسینی پیتەکە؛ لە نوسینی فەرمی‌دا نابێت بە پیتی بێ‌نیشانە بگۆڕدرێن، چونکە جیاوازیی ڕێنووسی دەهێننە ئاراوە. پیتەکانی Q، W و Xیش لە ئەلفبێی لاتینیی کورمانجی بەکاردێن.</p></section>
<section class="klesson-card"><h2>٣. پیت و دەنگ یەک شت نین</h2><p>پیت نیشانەی نوسراوە؛ دەنگ ئەو یەکەیە کە لە قسەکردندا دەبیسترێت. پەیوەندیی نێوان پیت و دەنگ بابەتێکی گرنگی فێربونی ڕێنووسە، بەڵام نابێت بە بێ پشکنینی دەنگییەوە وا دابنرێت کە هەر پیتێک لە هەمو وشە و شێوەزارێکدا تەنیا یەک دەنگی هەیە.</p></section>
<section class="klesson-card"><h2>٤. ڕاهێنان</h2><ol><li>ئەلفبێکە بە ڕیزبەندییەوە بخوێنەوە و بنووسە.</li><li>پیتە نیشانەدارەکان لە لیستەکەدا دیاری بکە.</li><li>بۆچی Ç و C، یان Ş و S، لە نوسینی فەرمی‌دا نابێت بە یەک شت دابنرێن؟</li></ol></section>
<section class="klesson-card"><h2>سەرچاوەکان</h2><ol><li>Haig, Geoffrey. (2018). “Northern Kurdish (Kurmanjî).” In Geoffrey Haig & Geoffrey Khan (eds.), <em>The Languages and Linguistics of Western Asia: An Areal Perspective</em>, pp. 106–158. De Gruyter Mouton. <a href="https://doi.org/10.1515/9783110421682-004" target="_blank" rel="noopener">DOI: 10.1515/9783110421682-004</a>.</li><li>Thackston, W. M. (2006). <em>Kurmanji Kurdish: A Reference Grammar with Selected Readings</em>. Harvard University.</li><li>University of Arizona, Iranian Languages. <a href="https://iranian-languages.arizona.edu/node/7" target="_blank" rel="noopener">Kurmanji Kurdish</a>.</li></ol><p class="klesson-note">سەرچاوەکان بۆ چوارچێوەی گشتیی زمان و ڕێنووس دانراون. بۆ وەشانی کۆتایی، دەبێت هەر نمونەیەکی ورد بە چاپی سەرچاوەی ڕێنووسەکەوە بگونجێندرێت.</p></section>'),
    ('kurmanji-course-1-lesson-03.html', 'kurmanji-course-1', 'ڤاوڵەکان و نیشانەنووسییان', '<section class="klesson-card"><h2>١. هەشت پیتی ڤاوڵ</h2><p>لە ڕێنووسی لاتینیی باوی کورمانجی، هەشت پیتی ڤاوڵ هەن:</p>
<table class="klesson-table"><thead><tr><th>پیت</th><th>تێبینیی ڕێنووسی</th><th>نمونە</th><th>واتا</th></tr></thead><tbody>
<tr><td>A a</td><td>پیتی ڤاوڵ</td><td>qaz</td><td>قاز</td></tr>
<tr><td>E e</td><td>جیاوازە لە Ê</td><td>belg</td><td>گەڵا</td></tr>
<tr><td>Ê ê</td><td>پیتی جیاواز بە نیشانەی ^</td><td>lêv</td><td>لێو</td></tr>
<tr><td>I i</td><td>جیاوازە لە Î</td><td>dil</td><td>دڵ</td></tr>
<tr><td>Î î</td><td>پیتی جیاواز بە نیشانەی ^</td><td>hîn</td><td>هێشتا</td></tr>
<tr><td>O o</td><td>پیتی ڤاوڵ</td><td>nod</td><td>نەوەد</td></tr>
<tr><td>U u</td><td>جیاوازە لە Û</td><td>qul</td><td>کون</td></tr>
<tr><td>Û û</td><td>پیتی جیاواز بە نیشانەی ^</td><td>bûz</td><td>سەهۆڵ</td></tr>
</tbody></table>
<p class="klesson-note">نمونەکان و واتاکانیان بە پشت‌بەستن بە خشتەی ڕێنووس و دەنگی کورمانجی لە سەرچاوەی زانکۆی ئەریزۆنا هەڵبژێردراون؛ لە بەکارهێنانی ڕۆژانەدا دەتوانێت هەندێک جیاوازیی شێوەزار هەبێت.</p></section>
<section class="klesson-card"><h2>٢. نیشانەی ^ بێ‌واتا نیە</h2><p>لە نوسینی کورمانجی، <strong>ê</strong> لە <strong>e</strong>، <strong>î</strong> لە <strong>i</strong>، و <strong>û</strong> لە <strong>u</strong> جیاوازن. بۆیە لە فێربون و نوسینی وشەکاندا پەیویستە نیشانەکە بە وردی بپارێزرێت. گۆڕینی پیتێک بە پیتێکی هاوشێوە، دەتوانێت شێوەی وشە بگۆڕێت یان ڕێنووسەکە نادروست بکات.</p><p>لە ڕووی دەنگناسییەوە، سەرچاوەکان جیاوازیی دەنگیی نێوان ئەم پیتانە بە شێوەی IPA ڕون دەکەنەوە؛ بەڵام باشترە فێرخواز تەنیا لەسەر هاوشێوەیی دەنگەکان لە زمانێکی دیکەوە بڕیار نەدات، چونکە هاوتاکردنەوەی دەنگ بە زمانی ئینگلیزی یان کوردیی ناوەندی تەواو و ورد نیە.</p></section>
<section class="klesson-card"><h2>٣. ڕاهێنان</h2><ol><li>هەشت پیتی ڤاوڵ بە پیتی گەورە و بچووک بنووسە.</li><li>جیاوازیی نوسینی e/ê، i/î و u/û دیاری بکە.</li><li>وشەکانی qaz، belg، lêv، dil، hîn، nod، qul و bûz بخوێنەوە و نیشانەی پیتەکان بپارێزە.</li></ol></section>
<section class="klesson-card"><h2>سەرچاوەکان</h2><ol><li>University of Arizona, Iranian Languages. <a href="https://iranian-languages.arizona.edu/node/7" target="_blank" rel="noopener">Kurmanji Kurdish — Phonology and Orthography</a> (خشتەی ڤاوڵ و نمونەی وشەکان).</li><li>Haig, Geoffrey. (2018). “Northern Kurdish (Kurmanjî).” In Geoffrey Haig & Geoffrey Khan (eds.), <em>The Languages and Linguistics of Western Asia: An Areal Perspective</em>, pp. 106–158. De Gruyter Mouton. <a href="https://doi.org/10.1515/9783110421682-004" target="_blank" rel="noopener">DOI</a>.</li><li>Thackston, W. M. (2006). <em>Kurmanji Kurdish: A Reference Grammar with Selected Readings</em>. Harvard University.</li></ol></section>'),
    ('kurmanji-course-1-lesson-04.html', 'kurmanji-course-1', 'کۆنسۆنەنتەکان و پەیوەندییان بە نوسینەوە', '<section class="klesson-card"><h2>١. کۆنسۆنەنت چیە؟</h2><p>کۆنسۆنەنت (consonant) دەنگێکە کە لە دروستبوونیدا هەوا لە ڕێگای دەمدا بە بەربەستێک یان تەنگەبەرێک ڕووبەڕوو دەبێتەوە. لە نوسینی کورمانجی، پیتەکانی ئەلفبێ بە پێی ڕێنووسی لاتینی بەکاردێن؛ بەڵام پیت و دەنگ یەک شت نین، چونکە پەیوەندیی نێوانیان لە هەمو شێوەزارەکاندا هەمیشە یەکسان نیە.</p></section>
<section class="klesson-card"><h2>٢. پیتە کۆنسۆنەنتەکان</h2><p>لە ئەلفبێی ٣١ پیتی کورمانجی، ئەمانە وەک پیتی کۆنسۆنەنت بەکاردێن:</p><table class="klesson-table"><thead><tr><th>پیت</th><th>تێبینیی خوێندنەوە</th></tr></thead><tbody>
<tr><td>B b</td><td>کۆنسۆنەنتی دەنگدار</td></tr><tr><td>C c</td><td>لە خشتەی IPAدا بە /d͡ʒ/ نوێنەرایەتی دەکرێت</td></tr><tr><td>Ç ç</td><td>/t͡ʃ/</td></tr><tr><td>D d</td><td>/d/</td></tr><tr><td>F f</td><td>/f/</td></tr><tr><td>G g</td><td>/g/</td></tr><tr><td>H h</td><td>/h/</td></tr><tr><td>J j</td><td>/ʒ/</td></tr><tr><td>K k</td><td>/k/ لە شێوەی گشتیی نوسین</td></tr><tr><td>L l</td><td>/l/</td></tr><tr><td>M m</td><td>/m/</td></tr><tr><td>N n</td><td>/n/</td></tr><tr><td>P p</td><td>/p/ لە شێوەی گشتیی نوسین</td></tr><tr><td>Q q</td><td>وەستانی بێ‌دەنگی لووتکەیی /q/</td></tr><tr><td>R r / RR rr</td><td>جیاوازیی لە نێوان tap و trill لە هەندێک نوسین و شێوەزاردا</td></tr><tr><td>S s</td><td>/s/</td></tr><tr><td>Ş ş</td><td>/ʃ/</td></tr><tr><td>T t</td><td>/t/ لە شێوەی گشتیی نوسین</td></tr><tr><td>V v</td><td>/v/</td></tr><tr><td>W w</td><td>/w/</td></tr><tr><td>X x</td><td>لە ڕێنووسی ستاندارددا دەنگی /χ/ نیشان دەدات؛ بە پێی شێوەزار دەکرێت جیاوازی هەبێت</td></tr><tr><td>Y y</td><td>/j/</td></tr><tr><td>Z z</td><td>/z/</td></tr></tbody></table>
<p class="klesson-note">ئەم خشتەیە بۆ ناسینی پیت و پەیوەندیی باویانە، نەک تۆماری تەواوی هەمو فونیمەکانی کورمانجی. سەرچاوەی زانکۆی ئەریزۆنا هەندێک جیاوازیی دەنگی و شێوەزاری وەک جیاوازیی aspirated/unaspirated و trill/tap ڕون دەکاتەوە کە هەمیشە لە ڕێنووسی ستاندارددا نیشان نادرێن.</p></section>
<section class="klesson-card"><h2>٣. پیتە هاوشێوەکان تێکەڵ مەکە</h2><ul><li><strong>C / Ç:</strong> دوو پیتی جیاوازن و بە دوو دەنگی جیاواز نوێنەرایەتی دەکرێن.</li><li><strong>S / Ş:</strong> نیشانەی ç/ş بەشێکە لە پیتەکە؛ لابردنی نیشانەکە ڕێنووس دەگۆڕێت.</li><li><strong>R / RR:</strong> لە هەندێک شێوەی نوسین، دووبارەکردنەوەی r دەتوانێت جیاوازیی trill لە tap نیشان بدات؛ بەڵام ئەم جیاوازییە لە هەمو شێوەزار و نوسینێکدا بە شێوەیەکی یەکسان نانووسرێت.</li><li><strong>X:</strong> لە ڕێنووسی ستانداردی کورمانجی، x پیتی سەربەخۆیە و نابێت بە ks یان پیتێکی دیکە بگۆڕدرێت.</li></ul></section>
<section class="klesson-card"><h2>٤. ڕاهێنان</h2><ol><li>پیتەکانی C، Ç، S، Ş و X لە ئەلفبێدا دیاری بکە.</li><li>ڕون بکەرەوە بۆچی پیت و فونیم یەک شت نین.</li><li>بە وشەیەک لە سەرچاوەی فێرکارییەکەوە نمونەی پیتی Ç یان Ş بدۆزەوە و بە ڕێنووسی ڕاست بنووسە.</li></ol></section>
<section class="klesson-card"><h2>سەرچاوەکان</h2><ol><li>University of Arizona, Iranian Languages. <a href="https://iranian-languages.arizona.edu/node/7" target="_blank" rel="noopener">Kurmanji Kurdish — Phonology and Orthography</a>.</li><li>Encyclopaedia Iranica. “Iranian Languages and Scripts: Writing Systems.” <a href="https://www.iranicaonline.org/articles/iran-vi3-writing-systems/" target="_blank" rel="noopener">بەشی سیستەمەکانی نوسین</a>.</li><li>Haig, Geoffrey. (2018). “Northern Kurdish (Kurmanjî).” In Geoffrey Haig &amp; Geoffrey Khan (eds.), <em>The Languages and Linguistics of Western Asia: An Areal Perspective</em>, pp. 106–158. Berlin: De Gruyter Mouton. <a href="https://doi.org/10.1515/9783110421682-004" target="_blank" rel="noopener">DOI: 10.1515/9783110421682-004</a>.</li></ol></section>'),
    ('kurmanji-course-1-lesson-05.html', 'kurmanji-course-1', 'پیتە تایبەتەکان: ç، ş، ê، î، û', '<section class="klesson-card"><h2>١. پێنج پیتەکە</h2><p>ئەلفبێی لاتینیی کورمانجی ٣١ پیتی هەیە. پێنج پیت کە بە نیشانەی جیاواز لە نوسینی ئینگلیزی دەردەکەون، بریتین لە <strong>ç، ş، ê، î، û</strong>. ئەم نیشانانە جوانکاری نین؛ بەشێکن لە شێوەی فەرمیی پیتەکە.</p><table class="klesson-table"><thead><tr><th>پیت</th><th>نمونەی کورمانجی</th><th>واتا</th><th>تێبینی</th></tr></thead><tbody>
<tr><td>ç</td><td>çak</td><td>باش</td><td>لە خشتەی زانکۆی ئەریزۆنا بە /t͡ʃ/ نوێنەرایەتی دەکرێت.</td></tr>
<tr><td>ş</td><td>şaş</td><td>هەڵە</td><td>/ʃ/؛ پیتی ş لە s جیاوازە.</td></tr>
<tr><td>ê</td><td>êş</td><td>ئازار</td><td>ڤاوڵێکی جیاواز لە e.</td></tr>
<tr><td>î</td><td>îro</td><td>ئەمڕۆ</td><td>ڤاوڵێکی جیاواز لە i.</td></tr>
<tr><td>û</td><td>bûz</td><td>سەهۆڵ</td><td>ڤاوڵێکی جیاواز لە u.</td></tr></tbody></table>
<p class="klesson-note">نمونە و واتاکان لە خشتەی ڕێنووس و دەنگناسیی کورمانجیی زانکۆی ئەریزۆنا وەردەگیرێن. دەربڕینی وردی دەنگەکان دەتوانێت بە شێوەزار بگۆڕێت؛ بۆیە ئەم وانەیە بنەمای نوسین دەخاتەڕوو، نەک هەمو جیاوازییە دەنگییەکان.</p></section>
<section class="klesson-card"><h2>٢. نیشانەکە لە نوسین دابمەزرێنە</h2><ul><li><strong>ç</strong> هەمیشە لە نوسین لە <strong>c</strong> جیاوازە؛ لەبیرت نەچێت نیشانەکە لاببەیت.</li><li><strong>ş</strong> لە <strong>s</strong> جیاوازە؛ نوسینی şaş بە شێوەی sash یان sas هەمان ڕێنووس نیە.</li><li><strong>ê</strong> لە <strong>e</strong>، <strong>î</strong> لە <strong>i</strong>، و <strong>û</strong> لە <strong>u</strong> جیاوازن. نیشانەی پیتەکە بە وردی بنووسە.</li><li>لە پیتی گەورەدا شێوەکان بریتین لە <strong>Ç، Ş، Ê، Î، Û</strong>.</li></ul></section>
<section class="klesson-card"><h2>٣. ڕاهێنانی نوسین</h2><ol><li>هەر پیتێک پێنج جار بە شێوەی گەورە و بچووک بنووسە: Ç ç، Ş ş، Ê ê، Î î، Û û.</li><li>ئەم وشانە لە ڕووی پیتە تایبەتەکەوە پۆلێن بکە: çak، şaş، êş، îro، bûz.</li><li>بە بێ گۆڕینی نیشانەکان، هەر وشەیەک لە خشتەکەوە دووبارە بنووسە.</li><li>بە وشەیەکی ڕاستەقینە لە سەرچاوەی فێرکاری، نمونەیەک بۆ ç و ş بدۆزەوە و لەگەڵ وانەکەدا تۆماری بکە.</li></ol></section>
<section class="klesson-card"><h2>سەرچاوەکان</h2><ol><li>University of Arizona, Iranian Languages. <a href="https://iranian-languages.arizona.edu/node/7" target="_blank" rel="noopener">Kurmanji Kurdish — Phonology and Orthography</a> (خشتەی پیت و نمونە وشەکان).</li><li>Haig, Geoffrey. (2018). “Northern Kurdish (Kurmanjî).” In Geoffrey Haig & Geoffrey Khan (eds.), <em>The Languages and Linguistics of Western Asia: An Areal Perspective</em>, pp. 106–158. De Gruyter Mouton. <a href="https://doi.org/10.1515/9783110421682-004" target="_blank" rel="noopener">DOI</a>.</li><li>Thackston, W. M. (2006). <em>Kurmanji Kurdish: A Reference Grammar with Selected Readings</em>. Harvard University.</li></ol></section>'),
    ('kurmanji-course-1-lesson-06.html', 'kurmanji-course-1', 'خوێندنەوە و نوسینی وشەی سادە', '<section class="klesson-card"><h2>١. ڕێکاری خوێندنەوە</h2><ol><li>سەرەتا هەمو پیتەکانی وشەکە دیاری بکە؛ بە تایبەتی ç، ş، ê، î و û.</li><li>وشەکە بە پیتەکانی خۆی دابەش بکە، بەڵام لە خوێندنەوەدا وشەکە بە شێوەیەکی سروشتی پێکەوە بخوێنەوە.</li><li>جیاوازیی e/ê، i/î و u/û بپارێزە؛ ئەم جیاوازییانە لە ڕێنووسدا گرنگن.</li><li>واتای وشەکە لە سەرچاوەی باوەڕپێکراو بپشکنە؛ لە تەنیا لەسەر هاوشێوەیی بە کوردیی ناوەندی یان ئینگلیزی بڕیار مەدە.</li></ol></section>
<section class="klesson-card"><h2>٢. وشەی سادە و نمونە</h2><table class="klesson-table"><thead><tr><th>وشە</th><th>واتای کوردی</th><th>تێبینیی ڕێنووسی</th></tr></thead><tbody>
<tr><td>av</td><td>ئاو</td><td>پیتی a و کۆنسۆنەنتی v</td></tr>
<tr><td>dil</td><td>دڵ</td><td>پیتی i جیاوازە لە î</td></tr>
<tr><td>lêv</td><td>لێو</td><td>ê بە نیشانەی خۆی بنووسە</td></tr>
<tr><td>hîn</td><td>هێشتا</td><td>î لە i جیاوازە</td></tr>
<tr><td>qaz</td><td>قاز</td><td>q پیتێکی سەربەخۆیە</td></tr>
<tr><td>qul</td><td>کون</td><td>u لە û جیاوازە</td></tr>
<tr><td>çak</td><td>باش</td><td>ç لە c جیاوازە</td></tr>
<tr><td>şaş</td><td>هەڵە</td><td>ş لە s جیاوازە</td></tr>
<tr><td>roj</td><td>ڕۆژ</td><td>j لە ڕێنووسی کورمانجی پیتی جیاوازە</td></tr>
<tr><td>yek</td><td>یەک</td><td>y دەنگی /j/ نیشان دەدات</td></tr>
</tbody></table><p class="klesson-note">واتاکان بەپێی خشتەی ڕێنووس و نمونەکانی زانکۆی ئەریزۆنا و سەرچاوەی وشەنامەی کورمانجی هاتوون. لە وشەنامەکاندا هەندێک وشە دەتوانێت واتای زیاتر هەبێت؛ لێرەدا تەنیا واتای سەرەکیی پەیوەندیدار بە ڕاهێنانەکە هاتووە.</p></section>
<section class="klesson-card"><h2>٣. ڕاهێنانی نوسین</h2><ol><li>وشەکانی av، dil، lêv، hîn و qaz بە پیتی گەورە و بچووک بنووسە.</li><li>لە وشەکانی çak و şaş نیشانەی تایبەتەکە دیاری بکە و ڕون بکەرەوە بۆچی نابێت لاببرێت.</li><li>وشەکانی qul و hîn بەراورد بکە و جیاوازیی u و î لە نوسینەکەدا دیاری بکە.</li><li>سێ وشە لە خشتەکە هەڵبژێرە؛ سەرەتا لەسەر کاغەز بنووسە، پاشان بە سەرچاوەکەوە بەراوردیان بکە.</li></ol></section>
<section class="klesson-card"><h2>٤. خۆهەڵسەنگاندن</h2><ul><li>دەتوانم پیتە تایبەتەکان بەبێ لابردنی نیشانەکانیان بنووسم.</li><li>دەتوانم جیاوازیی e/ê، i/î و u/û دیاری بکەم.</li><li>دەتوانم بۆ هەر وشەیەک واتا لە سەرچاوەدا بپشکنم، نەک بە گومان دیاری بکەم.</li></ul></section>
<section class="klesson-card"><h2>سەرچاوەکان</h2><ol><li>University of Arizona, Iranian Languages. <a href="https://iranian-languages.arizona.edu/node/7" target="_blank" rel="noopener">Kurmanji Kurdish — Phonology and Orthography</a>.</li><li>Yari. <a href="https://yari.krd/dictionary/" target="_blank" rel="noopener">Kurmanji–English word list</a>.</li><li>Thackston, W. M. (2006). <em>Kurmanji Kurdish: A Reference Grammar with Selected Readings</em>. Harvard University.</li></ol></section>'),
    ('kurmanji-course-1-lesson-10.html', 'kurmanji-course-1', 'دەربڕینە سەرەتاییەکان', '<section class="klesson-card"><h2>١. سڵاو و ماڵئاوایی</h2><table class="klesson-table"><thead><tr><th>دەربڕینی کورمانجی</th><th>واتا بە کوردی</th><th>کات و بەکارهێنان</th></tr></thead><tbody>
<tr><td>Silav!</td><td>سڵاو!</td><td>سڵاوکردنی گشتی.</td></tr>
<tr><td>Rojbaş!</td><td>بەیانیت باش / ڕۆژباش!</td><td>سڵاوێکی باو لە کاتی ڕۆژدا.</td></tr>
<tr><td>Şevbaş!</td><td>شەوت باش!</td><td>بۆ ماڵئاوایی، زۆرجار لە ئێوارە یان شەودا.</td></tr>
<tr><td>Bi xatirê te!</td><td>خواحافیز / ماڵئاوایی!</td><td>ماڵئاوایی؛ بەکارهێنان دەتوانێت بە کۆنتێکست بگۆڕێت.</td></tr>
<tr><td>Bi xêr hatî!</td><td>بەخێر بێیت!</td><td>بەخێرهاتن بۆ تاک؛ شێوەکە بەپێی ژمارە و ڕەگەز دەتوانێت بگۆڕێت.</td></tr>
</tbody></table><p class="klesson-note">دەربڕینەکان لە شێوەزار و بارودۆخی کۆمەڵایەتیی جیاوازدا هەندێک جیاوازییان هەیە. لە گفتوگۆی فەرمی و نافەرمی‌دا، کۆنتێکست و شێوەی بەکارهێنان لەبەرچاو بگرە.</p></section>
<section class="klesson-card"><h2>٢. ناساندن و پرسیارکردن لە بارودۆخ</h2><table class="klesson-table"><thead><tr><th>کورمانجی</th><th>واتا</th></tr></thead><tbody>
<tr><td>Tu çawa yî?</td><td>چۆنی؟ (بۆ تاک)</td></tr>
<tr><td>Ez baş im.</td><td>من باشم.</td></tr>
<tr><td>Navê min Azad e.</td><td>ناوی من ئازادە.</td></tr>
<tr><td>Tu kî yî?</td><td>تۆ کێیت؟</td></tr>
<tr><td>Ez ji ... me.</td><td>من خەڵکی ...م / لە ...م.</td></tr>
</tbody></table><p>لە نمونەی <em>Ez ji ... me</em> شوێنەکە بە ناوی گونجاو پڕ بکەرەوە. لە ڕستەی <em>Tu çawa yî?</em>، جێناوی <em>tu</em> بۆ تاکە؛ شێوەی بانگکردنی کۆ لە وانەکانی دواتردا دەخوێندرێتەوە.</p></section>
<section class="klesson-card"><h2>٣. سوپاس و داواکردنی یارمەتی</h2><table class="klesson-table"><thead><tr><th>کورمانجی</th><th>واتا</th><th>تێبینی</th></tr></thead><tbody>
<tr><td>Spas!</td><td>سوپاس!</td><td>دەربڕینی سوپاسگوزاری.</td></tr>
<tr><td>Ji kerema xwe.</td><td>تکایە.</td><td>داواکردنی ڕێزدارانە.</td></tr>
<tr><td>Erê.</td><td>بەڵێ.</td><td>وەڵامی ئەرێنی.</td></tr>
<tr><td>Na.</td><td>نەخێر.</td><td>وەڵامی نەرێنی.</td></tr>
<tr><td>Biborîne.</td><td>ببورە.</td><td>داوای لێبوردن؛ شێوە و ڕێنووس دەتوانێت لە سەرچاوەکاندا جیاواز بێت.</td></tr>
</tbody></table></section>
<section class="klesson-card"><h2>٤. گفتوگۆی کورت</h2><p><strong>A:</strong> Silav! Tu çawa yî?</p><p><strong>B:</strong> Silav! Ez baş im, spas. Tu çawa yî?</p><p><strong>A:</strong> Ez jî baş im.</p><p class="klesson-note">واتا: A سڵاو دەکات و دەپرسێت چۆنە. B وەڵام دەدات و سوپاس دەکات، پاشان پرسیارەکە دەگەڕێنێتەوە. وشەی <em>jî</em> لێرەدا واتای «هەروەها/هەروەها من» دەگەیەنێت.</p></section>
<section class="klesson-card"><h2>٥. ڕاهێنان</h2><ol><li>بە کورمانجی سڵاو بکە و بپرسە کەسەکە چۆنە.</li><li>بە ڕستەیەکی سادە خۆت بناسێنە: <em>Navê min ... e.</em></li><li>بۆ «سوپاس»، «تکایە» و «بەڵێ» هاوتای کورمانجی بنووسە.</li><li>گفتوگۆی دوو کەسییەک دروست بکە کە تێیدا سڵاو، پرسیار لە بارودۆخ و سوپاس هەبێت.</li><li>دەربڕینێک هەڵبژێرە و لە دوو سەرچاوەدا شێوەی نوسین و واتاکەی بەراورد بکە.</li></ol></section>
<section class="klesson-card"><h2>٦. سەرچاوەکان</h2><ol><li>Yari. <a href="https://yari.krd/learn/kurdish-greetings/" target="_blank" rel="noopener">Kurdish greetings and everyday phrases</a>.</li><li>Yari. <a href="https://yari.krd/dictionary/" target="_blank" rel="noopener">Kurmanji–English dictionary</a>.</li><li>W. M. Thackston. <em>Kurmanji Kurdish: A Reference Grammar with Selected Readings.</em> <a href="https://sites.fas.harvard.edu/~iranian/Kurmanji/kurmanji_complete.pdf" target="_blank" rel="noopener">PDF</a>.</li></ol></section>'),
    ('kurmanji-course-1-lesson-25.html', 'kurmanji-course-1', 'حاڵەتی ڕاستەوخۆ و ناڕاستەوخۆ', '<section class="klesson-card"><h2>١. حاڵەت چیە؟</h2><p>حاڵەتی ڕێزمانی شێوەیەکە کە پەیوەندیی ناو یان جێناو بە ڕۆڵی لە ڕستەدا پیشان دەدات. لە کورمانجیدا جیاوازیی نێوان حاڵەتی ڕاستەوخۆ (<em>direct</em>) و ناڕاستەوخۆ (<em>oblique</em>) گرنگە؛ بە تایبەتی لە جێناوەکان، بەرکاری کردارە تێپەڕەکانی ئێستا، دوای ئامرازی پەیوەندی، خاوەنداری و ڕستەی ڕابردووی تێپەڕدا.</p><p class="klesson-note">ناوی «ڕاستەوخۆ/ناڕاستەوخۆ» لێرە ناوی دوو حاڵەتی ڕێزمانیی کورمانجییە، نەک تەنیا مانای ئاساییی وشەکانی «ڕاستەوخۆ» و «ناڕاستەوخۆ».</p></section>
<section class="klesson-card"><h2>٢. گۆڕانی ناو بە پێی حاڵەت</h2><p>فۆڕمی حاڵەتی ناو بە پێی ڕەگەزی ڕێزمانی، ژمارە و نیشانەی نەناسراوی دەگۆڕێت. لە نمونەی ستانداردی خوارەوەدا، ناوی نێری تاک زۆرجار لە حاڵەتی ڕاستەوخۆدا بێ کۆتاییی دیارە، بەڵام ناوی مێ و ناوی نەناسراو دەتوانن کۆتاییی دیار هەبێت.</p><table class="klesson-table"><thead><tr><th>ڕاستەوخۆ</th><th>ناڕاستەوخۆ</th><th>واتا</th></tr></thead><tbody><tr><td>gund</td><td>gund-î</td><td>گوند (نێری تاک، ناسراو)</td></tr><tr><td>gund-ek</td><td>gund-ek-î</td><td>گوندێک (نێری تاک، نەناسراو)</td></tr><tr><td>jin</td><td>jin-ê</td><td>ژن (مێی تاک، ناسراو)</td></tr><tr><td>jin-ek</td><td>jin-ek-ê</td><td>ژنێک (مێی تاک، نەناسراو)</td></tr></tbody></table><p class="klesson-note">خشتەی سەرەوە نمونەی ڕێزمانی ستانداردە و لەسەر فۆڕمەکانی <em>gund</em> و <em>jin</em> دامەزراوە. لە هەندێک شێوەزاردا، بە تایبەتی لە ناوی نێری تاکی بەڕووت، نیشانەی حاڵەتی ناڕاستەوخۆ دەکرێت لە ڕووی دەرەوەدا نەردرکێت؛ بەڵام لەگەڵ نیشانەی نەناسراوی <em>-ek</em>، نیشانەکە بە شێوەیەکی ڕوونتر دەردەکەوێت. بۆیە <em>mirov</em> و <em>mirov-ek</em> لەم خشتەیەدا وەک هاوتای فۆڕمە ستانداردەکانی خشتەی سەرەکی نیشان نەدراون. جیاوازیی شێوەزارەکان دەبێت بە سەرچاوەی دیاریکراوەوە پشکنین بکرێت.</p></section>
<section class="klesson-card"><h2>٣. جێناوە ڕاستەوخۆ و ناڕاستەوخۆکان</h2><p>جێناوە سەربەخۆکانیش دوو کۆمەڵە فۆڕمیان هەیە. فۆڕمی ڕاستەوخۆی ew بۆ تاکی نێر، تاکی مێ و کۆ بەکاردێت؛ واتە ژمارە و ڕەگەز هەمیشە لە خودی ئەم فۆڕمەوە دیار نابن و سیاق یارمەتی دەدات. بە پێچەوانەوە، لە فۆڕمی ناڕاستەوخۆدا لە تاکدا wî بۆ نێر و wê بۆ مێ بەکاردێت، بەڵام فۆڕمی کۆ wan ـە. لە ڕستەی ئێستادا، جێناوی ڕاستەوخۆ زۆرجار بکەرە؛ فۆڕمی ناڕاستەوخۆ لە بەرکار، دوای ئامرازی پەیوەندی و لە دەربڕینی خاوەنداریدا دەردەکەوێت. لە ڕابردووی کردارە تێپەڕەکاندا، ئەم دابەشبوونە گرنگترە و پەیوەندی بە سیستەمی ئەرجەتیڤی کورمانجییەوە هەیە.</p><table class="klesson-table"><thead><tr><th>ڕاستەوخۆ</th><th>ناڕاستەوخۆ</th><th>کەس</th></tr></thead><tbody><tr><td>ez</td><td>min</td><td>من</td></tr><tr><td>tu</td><td>te</td><td>تۆ</td></tr><tr><td>ew</td><td>wî / wê</td><td>ئەو (لە تاکدا wî بۆ نێر و wê بۆ مێ؛ لە کۆدا wan)</td></tr><tr><td>em</td><td>me</td><td>ئێمە</td></tr><tr><td>hûn</td><td>we</td><td>ئێوە</td></tr><tr><td>ew</td><td>wan</td><td>ئەوان</td></tr></tbody></table></section>
<section class="klesson-card"><h2>٤. حاڵەت لە ڕستەی ئێستا و ڕابردوودا</h2><p>لە ڕستەی ئێستای تێپەڕدا، بکەر زۆرجار لە حاڵەتی ڕاستەوخۆ و بەرکار لە ناڕاستەوخۆدا دێت:</p><p><strong>Ez wî mirovî dibînim.</strong><br>من ئەو پیاوە دەبینم.</p><p class="klesson-note">شیکردنەوە: <em>ez</em> بکەری ڕاستەوخۆیە؛ <em>wî</em> و <em>mirovî</em> لەم ڕستەیەدا فۆڕمی ناڕاستەوخۆن. لە ڕستەی ئێستای تێپەڕدا کردار لەگەڵ بکەر ڕێکدەکەوێت.</p><p>لە ڕستەی ڕابردووی تێپەڕدا، کورمانجی ڕێکخستنی ئەرجەتیڤی بەکاردەهێنێت: بکەری ڕێزمانی زۆرجار لە حاڵەتی ناڕاستەوخۆیە و بەرکار لە حاڵەتی ڕاستەوخۆدا دێت.</p><p><strong>Min ew dît.</strong><br>من ئەوم بینی.</p><p class="klesson-note">شیکردنەوە: <em>min</em> بکەری ناڕاستەوخۆیە؛ <em>ew</em> بەرکاری ڕاستەوخۆیە. <em>dît</em> کردارەکەی ڕابردووی تێپەڕە و لە ئەم نمونەیەدا لەگەڵ بەرکاری تاک ڕێکدەکەوێت.</p><p class="klesson-note">ئەم نموونانە بنەڕەتیین. لە ڕستەی ڕابردووی تێپەڕدا، لە ڕێکخستنی ئەرجەتیڤی بنەڕەتیدا کردار لەگەڵ بەرکار ڕێکدەکەوێت، نەک لەگەڵ بکەر. بەڵام لە کورمانجیدا ڕێککەوتنی کردار و حاڵەتی بەرکار لە هەندێک شێوەزار و سیاقی تایبەتدا جیاوازییان هەیە؛ بۆیە ئەم یاسایە وەک بنەمای گشتی فێر دەکرێت، نەک وەک یاسایەکی بێ‌هەڵوێست بۆ هەمو نمونەکان.</p></section>
<section class="klesson-card"><h2>٥. ڕاهێنان</h2><ol><li>جیاوازیی نێوان <em>gund</em> و <em>gund-î</em> لە ڕووی حاڵەتی ڕێزمانی ڕون بکەوە.</li><li>فۆڕمە ڕاستەوخۆ و ناڕاستەوخۆکانی <em>ez/min</em> و <em>tu/te</em> لەبەر بکە.</li><li>لە ڕستەی <em>Ez wî mirovî dibînim</em> بکەر و بەرکار دیاری بکە.</li><li>لە ڕستەی <em>Min ew dît</em> ڕۆڵی <em>min</em> و <em>ew</em> باس بکە.</li><li>بە وشەی خۆت ڕون بکەوە بۆچی ڕابردووی کردارە تێپەڕەکان لە کورمانجیدا سیستەمی جیاوازی حاڵەت هەیە.</li></ol></section>
<section class="klesson-card"><h2>٦. سەرچاوەکان</h2><ol><li>Geoffrey Haig (2018), <a href="https://doi.org/10.1515/9783110421682-004" target="_blank" rel="noopener"><em>Northern Kurdish (Kurmanjî)</em></a>, in Geoffrey Haig &amp; Geoffrey Khan (eds.), <em>The Languages and Linguistics of Western Asia: An Areal Perspective</em>, pp. 106–158, Table 7 and sections on case and ergativity.</li><li>University of Arizona, <a href="https://iranian-languages.arizona.edu/node/7" target="_blank" rel="noopener">Kurmanji Kurdish</a>, noun case, pronouns and past tense.</li><li>Thackston, W. M., <a href="https://sites.fas.harvard.edu/~iranian/Kurmanji/kurmanji_complete.pdf" target="_blank" rel="noopener"><em>Kurmanji Kurdish: A Reference Grammar with Selected Readings</em></a>.</li></ol></section>'),
    ('kurmanji-course-2-lesson-04.html', 'kurmanji-course-2', 'ناوی دیار و نادیار؛ پاشگری -ek', '<section class="klesson-card"><h2>١. نادیاری بە -ek</h2><p>لە نمونەی باوی کورمانجی‌دا gund ‘گوند’ و gundek ‘گوندێک’ بەراورد دەکرێن. -ek نیشانەی نادیاریی تاکە؛ لە شیکردنەوەی ورددا پەیویستە فۆڕمی حاڵەتی ڕاستەوخۆ/ناڕاستەوخۆ و ئەزافەش لەبەرچاو بگیرێت.</p></section><section class="klesson-card"><h2>٢. ناوی بێ پاشگر</h2><p>ناوی بێ -ek هەمیشە بە واتای دیار نیە؛ بە پێی سیاق دەتوانێت ئاماژە بە شتێکی ناسراو، جۆرێک بە گشتی، یان شتێک کە لە گفتوگۆدا دیارە بکات. بۆیە پەیویستە ڕستە و سیاق بخوێندرێتەوە.</p></section><section class="klesson-card"><h2>٣. حاڵەت و فۆڕمی نادیار</h2><p>لە ستانداردی کورمانجی‌دا شێوەی ناوی نادیار دەتوانێت لە حاڵەتی ناڕاستەوخۆدا نیشانەی زیاتر وەربگرێت؛ وەک <em>gund-ek-î</em> و <em>jin-ek-ê</em>. لەم فۆڕمانەدا <em>-ek</em> نیشانەی نادیاریی تاکە، و کۆتاییی <em>-î/-ê</em> فۆڕمی حاڵەتی ناڕاستەوخۆی ناوەکە نیشان دەدات. ئەمە لە نمونەی <em>bajar-ek-î mezin</em> جیاوازە: لەو پێکهاتەیەدا <em>-î</em> پەیوەندیی ئەزافە دروست دەکات بۆ بەستنەوەی هاوەڵناوی <em>mezin</em> بە ناوەکە. واتە فۆڕمی ڕووکەشی هاوشێوە هەمیشە ئەرکی ڕێزمانیی یەکسان نیە؛ پێویستە پێکهاتە و سیاق بپشکنرێت.</p></section>
<section class="klesson-card"><h2>تێبینیی مێتۆدی</h2><p class="klesson-note">Haig (2018)، لە بەشی ناوی کورمانجی و خشتەی حاڵەت، جیاوازی حاڵەتی ڕاستەوخۆ/ناڕاستەوخۆ و فۆڕمی ناوی نادیار پیشان دەدات. شێوەی هەر ناوێک بە ڕەگەز، حاڵەت و سیاقەوە پەیوەستە.</p></section>
<section class="klesson-card"><h2>پرسیارەکانی پێداچوونەوە</h2><ol><li>پاشگری -ek زۆرجار چی نیشان دەدات؟</li><li>بۆچی ناوی بێ -ek هەمیشە دیار نیە؟</li><li>چۆن حاڵەت دەتوانێت فۆڕمی ناوی نادیار بگۆڕێت؟</li></ol></section>
<section class="klesson-card"><h2>سەرچاوەکان</h2><ul><li>Haig, Geoffrey. (2018). “Northern Kurdish (Kurmanjî).” In Geoffrey Haig & Geoffrey Khan (eds.), <em>The Languages and Linguistics of Western Asia: An Areal Perspective</em>, pp. 106–158. Berlin: De Gruyter Mouton. <a href="https://doi.org/10.1515/9783110421682-004" target="_blank" rel="noopener">DOI: 10.1515/9783110421682-004</a>.</li><li>Thackston, W. M. (2006). <em>Kurmanji Kurdish: A Reference Grammar with Selected Readings.</em> Renas Media. <a href="https://kurdishacademy.org/?page_id=623" target="_blank" rel="noopener">پەڕەی کتێب لە ئەکادێمیای کوردی</a>.</li></ul><p class="klesson-note">نمونە و یاساکان لە چوارچێوەی کورمانجیی ستاندارددا پێشکەش کراون؛ بۆ جیاوازیی شێوەزار و فۆڕمی تایبەت، دەبێت سەرچاوە و سیاق دیاری بکرێن.</p></section>'),
    ('kurmanji-course-2-lesson-06.html', 'kurmanji-course-2', 'خاوەنداری و جێناوە خاوەندارییەکان', '<section class="klesson-card"><h2>١. خاوەندار بە ئەزافە</h2><p>پێکهاتەی ئەزافە دەتوانێت پەیوەندیی خاوەنداری نیشان بدات. لە نمونەی Haig (2018)، <em>mal-a me</em> ‘ماڵی ئێمە’، <em>-a</em> پەیوەندیی ئەزافەی نێوان ناو و جێناوی خاوەندار دروست دەکات؛ <em>me</em> فۆڕمی ناڕاستەوخۆی جێناوی کەسیی <em>em</em> ـە و لێرەدا وەک خاوەندار بەکاردێت. بۆیە نابێت <em>-a</em> بە نیشانەی خاوەنداریی سەربەخۆ یان <em>me</em> بە فۆڕمی ڕاستەوخۆ تێبگەین. فۆڕمی ئەزافە لەگەڵ ناوی سەرەکی پەیوەستە.</p></section><section class="klesson-card"><h2>٢. جێناوی خاوەنداری</h2><p>جێناوە خاوەندارییەکان لە سیاقە جیاوازەکاندا بەکاردێن و فۆڕمیان بە پێی کەس و ژمارە دەگۆڕێت. پەیویستە جێناوی کەسیی سەربەخۆ لە فۆڕمی خاوەنداری و لە جێناوی ناو ڕستە جیا بکرێتەوە.</p></section><section class="klesson-card"><h2>٣. جێناوی خۆ (xwe)</h2><p><em>xwe</em> جێناوێکی خۆگەڕە و لە فۆڕمەکەیدا بە پێی کەس و ژمارە ناگۆڕێت. ئەگەر خاوەندار لە هەمان ڕستەدا بگەڕێتەوە بۆ بکەر، لە کورمانجیی ستاندارددا <em>xwe</em> بەکاربهێنە، نەک جێناوی کەسیی ناڕاستەوخۆی <em>min</em>. بۆ نمونە: <em>Ez li mal-a xwe me.</em> «من لە ماڵی خۆمم». لەم سیاقەدا <em>mal-a min</em> وەک خاوەنداریی هاوئاماژەی هەمان ڕستە ڕاست نیە. بەڵام ئەگەر خاوەندار بۆ کەسێکی دیکە بگەڕێتەوە، پێویستە ئاماژەی ڕستەی تەواو بپشکنرێت.</p></section>
<section class="klesson-card"><h2>تێبینیی مێتۆدی</h2><p class="klesson-note">نمونەی <em>mal-a me</em> لە Haig (2018)، §2.3.1، نمونەی (5) هاتووە؛ لێکدانەوەی <em>xwe</em> وەک جێناوی خۆگەڕ لە §2.2.3 (Pronouns) هاتووە. لە ستانداردی کورمانجی‌دا <em>xwe</em> بۆ خاوەنداریی هاوئاماژە بە بکەری هەمان ڕستە بەکاردێت؛ جیاوازیی شێوەزار، بە تایبەتی کورمانجیی ڕۆژئاوا، دەبێت جیاواز بپشکنرێت. سەرچاوە: <a href="https://doi.org/10.1515/9783110421682-004" target="_blank" rel="noopener">Haig (2018)</a>.</p></section>
<section class="klesson-card"><h2>پرسیارەکانی پێداچوونەوە</h2><ol><li>ئەزافە چۆن خاوەنداری دەردەبڕێت؟</li><li>جیاوازی جێناوی کەسی و خاوەنداری چیە؟</li><li>xwe لە چ جۆر سیاقێکدا بەکاردێت؟</li></ol></section>
<section class="klesson-card"><h2>سەرچاوەکان</h2><ul><li>Haig, Geoffrey. (2018). “Northern Kurdish (Kurmanjî).” In Geoffrey Haig & Geoffrey Khan (eds.), <em>The Languages and Linguistics of Western Asia: An Areal Perspective</em>, pp. 106–158. Berlin: De Gruyter Mouton. <a href="https://doi.org/10.1515/9783110421682-004" target="_blank" rel="noopener">DOI: 10.1515/9783110421682-004</a>.</li><li>Thackston, W. M. (2006). <em>Kurmanji Kurdish: A Reference Grammar with Selected Readings.</em> Renas Media. <a href="https://kurdishacademy.org/?page_id=623" target="_blank" rel="noopener">پەڕەی کتێب لە ئەکادێمیای کوردی</a>.</li></ul><p class="klesson-note">نمونە و یاساکان لە چوارچێوەی کورمانجیی ستاندارددا پێشکەش کراون؛ بۆ جیاوازیی شێوەزار و فۆڕمی تایبەت، دەبێت سەرچاوە و سیاق دیاری بکرێن.</p></section>'),
    ('kurmanji-course-2-lesson-09.html', 'kurmanji-course-2', 'کاتی ئێستا، ڕابردوو و داهاتوو', '<section class="klesson-card"><h2>١. کاتی ئێستا</h2><p>لە کاتی ئێستادا، پێشگر و فۆڕمی کردار دەتوانن زانیاریی کات و ڕەوش بگەیەنن. بۆ نمونە، فۆڕمەکانی di- لە زۆر کردارەکاندا لە پێکهاتەی ئێستادا دەردەکەون؛ بەڵام کردارە تایبەتەکان فۆڕمی جیاوازیان هەیە.</p></section><section class="klesson-card"><h2>٢. کاتی ڕابردوو</h2><p>ڕابردوو یەک شێوەی سادە نیە: جیاوازی نێوان کردارە تێپەڕ و ناتێپەڕەکان و فۆڕمەکانی کردار لە ڕێکخستنی ڕستەدا کاریگەری هەیە. لە ڕستەی ڕابردووی کردارە تێپەڕەکاندا سیستەمی حاڵەت گرنگە.</p></section><section class="klesson-card"><h2>٣. داهاتوو و واتای کات</h2><p>واتای داهاتوو دەتوانێت بە پێکهاتەی کردار و وشەی یاریدەدەر دەرببڕدرێت؛ شێوەی بەکارهێنان بە سیاق و جۆری ڕستەوە پەیوەستە. لە شیکردنەوەدا فۆڕمی کردار لەگەڵ نیشانەکانی کات و سیاق بە یەکەوە بخوێنەوە.</p></section>
<section class="klesson-card"><h2>٤. بەراوردی فۆڕمەکانی کردار</h2><p>لە نمونەکانی Haig (2018)، خشتەی ١٤، <code>ez dibêjim</code> فۆڕمی ئێستایە؛ <code>ez hatim</code> ڕابردووی کرداری ناتێپەڕە؛ <code>min xwar</code> ڕابردووی کرداری تێپەڕە. لە ڕستەی ڕابردووی تێپەڕدا، فۆڕمی جێناو و ڕێککەوتنی کردار لەگەڵ ئەوەی لە ڕستەی ئێستادا دەبینرێت جیاوازە.</p><p>بۆ جیاکردنەوەی ڕابردووی سادە لە ڕابردووی بەردەوام/ناکامڵ، سەرچاوە ئەم بەراوردەش دەدات: <code>ez hatim</code> (ڕابردووی سادەی ناتێپەڕ) لە بەرابەر <code>ez dihatim</code> (ڕابردووی بەردەوامی ناتێپەڕ)، هەروەها <code>min xwar</code> لە بەرابەر <code>min dixwar</code>.</p><p>بۆ داهاتوو، Haig (§2.6.4) نمونەی <code>ew dē mesel-ē ji te re bēž-e</code> دەهێنێتەوە: «ئەو کێشەکە بۆ تۆ دەڵێت». لەو نمونەیەدا <code>dē</code> نیشانەی داهاتووە و کردارەکە فۆڕمی subjunctive ـە. ئەم نووسینەی لاتینیە بە شێوەی سەرچاوە پارێزراوە؛ فۆڕمی نوێی دروستکراو نیە.</p></section>
<section class="klesson-card"><h2>تێبینیی مێتۆدی</h2><p class="klesson-note">ئەم وانەیە پێشەکییە بۆ سیستەمی کات و ڕەوش. خشتەی پارادایمی تەواو پەیویستی بە سەرچاوەی تایبەت و دیاریکردنی شێوەزار هەیە؛ لێرەدا فۆڕمی ناپشکنراو دروست نەکراوە.</p></section>
<section class="klesson-card"><h2>پرسیارەکانی پێداچوونەوە</h2><ol><li>پێشگری di- لە زۆر کردارەکانی کاتی ئێستادا چ ڕۆڵێکی هەیە؟</li><li>بۆچی ڕابردووی کردارە تێپەڕەکان بە جیاوازی لە کردارە ناتێپەڕەکان دەخوێندرێتەوە؟</li><li>داهاتوو بۆچی نابێت بە یاسای پاشگری یەکسان کورت بکرێتەوە؟</li></ol></section>
<section class="klesson-card"><h2>سەرچاوەکان</h2><ul><li>Haig, Geoffrey. (2018). “Northern Kurdish (Kurmanjî).” In Geoffrey Haig & Geoffrey Khan (eds.), <em>The Languages and Linguistics of Western Asia: An Areal Perspective</em>, pp. 106–158. Berlin: De Gruyter Mouton. <a href="https://doi.org/10.1515/9783110421682-004" target="_blank" rel="noopener">DOI: 10.1515/9783110421682-004</a>.</li><li>Thackston, W. M. (2006). <em>Kurmanji Kurdish: A Reference Grammar with Selected Readings.</em> Renas Media. <a href="https://kurdishacademy.org/?page_id=623" target="_blank" rel="noopener">پەڕەی کتێب لە ئەکادێمیای کوردی</a>.</li></ul><p class="klesson-note">نمونە و یاساکان لە چوارچێوەی کورمانجیی ستاندارددا پێشکەش کراون؛ بۆ جیاوازیی شێوەزار و فۆڕمی تایبەت، دەبێت سەرچاوە و سیاق دیاری بکرێن.</p></section>'),
    ('kurmanji-course-2-lesson-10.html', 'kurmanji-course-2', 'ڕستەی نەفی و پرسیاری', '<section class="klesson-card"><h2>١. نەفیی کردار</h2><p>لە زۆر فۆڕمەکانی کاتی ئێستای کورمانجی‌دا، na- بۆ نەفی بەکاردێت و لە بەرابەر di- دێت؛ بەڵام کردارە تایبەتەکان هەن، بۆیە یاساکە نابێت بەبێ پشکنین بۆ هەمو کردارەکان بگشتێندرێت.</p></section><section class="klesson-card"><h2>٢. نەفیی ڕستەی ناوەکی</h2><p>نەفیی ڕستەی ناوەکی و نەفیی کردار هەمیشە بە هەمان فۆڕم دروست نابن. فۆڕمی نەفی دەبێت بە پێی جۆری پێکهاتە و کردار بپشکنرێت.</p></section><section class="klesson-card"><h2>٣. پرسیاری بەڵێ/نەخێر و وشە پرسیاری</h2><p>پرسیاری بەڵێ/نەخێر دەتوانێت بە ئاواز و سیاق ناسرێتەوە؛ پرسیاری زانیاریییش وشەی پرسیاری وەک کێ، چی، لە کوێ یان کەی بەکار دەهێنێت. ڕیزبەندی وشەکان لە ڕستەی پرسیاریدا دەبێت بە پێی شێوەی ستاندارد و سیاق بپشکنرێت.</p></section>
<section class="klesson-card"><h2>٤. نمونەی نەفی لە سەرچاوەی زانستی</h2><p>Haig (2018)، لە بەشی پێشگری نەفی، دەڵێت <code>na-</code> لە زۆر فۆڕمەکانی ئێستادا جێگای <code>di-</code> دەگرێتەوە؛ بەڵام ئەمە یاسایەکی بێ‌استثنا نیە. بۆ دوو کردارەکەی <code>zanîn</code> «زانین» و <code>karîn</code> «توانین»، نمونەکانی <code>nizanim</code> «نازانم» و <code>nikarim</code> «ناتوانم» هاتوون.</p><p>لە ڕابردوودا، سەرچاوە ئەم بەراوردە دەدات: <code>ne-hatin</code> «نەهاتن» و <code>ne-di-hatin</code> «نەدەهاتن/لە هاتندا نەبوون». لێرەدا <code>ne-</code> لەگەڵ فۆڕمی ڕابردووی سادە یان بەردەوام بەکاردێت. شێوە و واتای ورد دەبێت لەگەڵ کات، جۆری کردار و شێوەزار بخوێندرێتەوە.</p><p class="klesson-note">ئەم فۆڕمانە وەک نووسینی لاتینیی سەرچاوە پارێزراون؛ لە نمونەی تاکەوە یاسای گشتی بۆ هەمو کردارەکان مەدەرهێنە.</p></section>
<section class="klesson-card"><h2>تێبینیی مێتۆدی</h2><p class="klesson-note">فۆڕمەکانی نەفی و پرسیار لە کردارە جیاوازەکاندا بەراورد بکە؛ یاسایەکی گشتی لە نمونەی تاکەوە مەدەرهێنە.</p></section>
<section class="klesson-card"><h2>پرسیارەکانی پێداچوونەوە</h2><ol><li>na- لە زۆر فۆڕمەکانی کاتی ئێستادا چی دەکات؟</li><li>جیاوازی نەفیی کردار و ڕستەی ناوەکی چیە؟</li><li>دوو جۆری پرسیاری سەرەکی چین؟</li></ol></section>
<section class="klesson-card"><h2>سەرچاوەکان</h2><ul><li>Haig, Geoffrey. (2018). “Northern Kurdish (Kurmanjî).” In Geoffrey Haig & Geoffrey Khan (eds.), <em>The Languages and Linguistics of Western Asia: An Areal Perspective</em>, pp. 106–158. Berlin: De Gruyter Mouton. <a href="https://doi.org/10.1515/9783110421682-004" target="_blank" rel="noopener">DOI: 10.1515/9783110421682-004</a>.</li><li>Thackston, W. M. (2006). <em>Kurmanji Kurdish: A Reference Grammar with Selected Readings.</em> Renas Media. <a href="https://kurdishacademy.org/?page_id=623" target="_blank" rel="noopener">پەڕەی کتێب لە ئەکادێمیای کوردی</a>.</li></ul><p class="klesson-note">نمونە و یاساکان لە چوارچێوەی کورمانجیی ستاندارددا پێشکەش کراون؛ بۆ جیاوازیی شێوەزار و فۆڕمی تایبەت، دەبێت سەرچاوە و سیاق دیاری بکرێن.</p></section>')
  ) AS expected(lesson_key, course_id, title, content_html)
    ON actual.lesson_key = expected.lesson_key
   AND actual.course_id IS NOT DISTINCT FROM expected.course_id
   AND actual.title IS NOT DISTINCT FROM expected.title
   AND actual.content_html IS NOT DISTINCT FROM expected.content_html
  FOR UPDATE OF actual;

  GET DIAGNOSTICS matched_rows = ROW_COUNT;
  IF matched_rows <> 12 THEN
    RAISE EXCEPTION USING
      ERRCODE = '55000',
      MESSAGE = format(
        'Kurmanji content reconciliation aborted: expected 12 untouched release rows, found %s. No lesson payload was updated.',
        matched_rows
      );
  END IF;
END;
$preflight$;

DO $apply$
DECLARE
  affected_rows integer;
BEGIN
  WITH changed AS (
    INSERT INTO public.lesson_content
      (lesson_key, course_id, title, content_html, updated_at)
    VALUES
    ('kurmanji-course-1-lesson-01.html','kurmanji-course-1','ناسینی کورمانجی و چوارچێوەی ڕێنووسی لاتینی','<section class="klesson-card"><h2>١. کورمانجی چیە؟</h2><p>کورمانجی (Kurmancî) یەکێکە لە شێوە و ڕێڕەوە زمانیە سەرەکییەکانی کوردی. لە زۆرێک لە بەکارهێنانە نوسراوە هاوچەرخەکاندا، کورمانجی بە ئەلفبێی لاتینیی هاوار دەنووسرێت. ئەم وانەیە ئەم سیستەمەی نوسین دەکاتە بابەتی سەرەکی؛ بەڵام نابێت ئەلفبێی نوسین لە خودی زمان یان لە هەمو تایبەتمەندییە دەنگییەکانی جیاوازییە زمانیەکان یەکسان بگیرێت.</p></section>
<section class="klesson-card"><h2>٢. جیاوازیی زمان، ئەلفبێ و ڕێنووس</h2><ul><li><strong>زمان:</strong> سیستەمی گشتیی پەیوەندی و ڕێکخستنی زمانیە.</li><li><strong>ئەلفبێ:</strong> کۆمەڵە نیشانەی نوسینە کە بۆ نوسینی زمان بەکاردێن.</li><li><strong>ڕێنووس:</strong> ڕێساکانی نوسینی وشە و بەکارهێنانی نیشانەکانی نوسینە.</li></ul><p>لە فێربونی کورمانجی‌دا، ناسینی پیتەکان پێشەنگییەکی گرنگە؛ بەڵام تەنیا زانینی ناوی پیتەکان بەس نیە. فێرخواز دەبێت فۆڕمی نووسراو، خوێندنەوەی باو و شوێنی پیتەکان لە وشەدا بە یەکەوە فێرببێت.</p></section>
<section class="klesson-card"><h2>٣. سنووری ڕێڕەوی ئەم کۆرسە</h2><p>کۆرسی یەکەم لە ٢٦ وانەدا لە ناساندنی سیستەمی نوسینەوە دەگاتە خوێندنەوە و نوسینی وشە و ڕستەی سادە. بابەتەکانی مۆرفۆلۆجی و ڕێزمان بە شێوەیەکی ڕێک‌خراوتر لە کۆرسی دووەمدا دەخوێندرێنەوە.</p><div class="klesson-note">تێبینیی زانستی: کورمانجی لە ناوچە و کۆمەڵگە جیاوازەکاندا هەندێک جیاوازیی دەربڕین و بەکارهێنانی هەیە. لە وانەکانی داهاتوودا نمونەکان بە پشت‌بەستن بە سەرچاوەی دیاریکراو دەخرێنەڕوو؛ نابێت شێوەیەکی تایبەت بە هەمو بەکارهێنانەکان بگشتێندرێت.</div></section>
<section class="klesson-card"><h2>٤. پێداچوونەوە</h2><ol><li>جیاوازی نێوان ئەلفبێ و ڕێنووس چیە؟</li><li>بۆچی پەیویستە سیستەمی نوسین لە خودی زمان جیا بکرێتەوە؟</li><li>ئەم کۆرسە چی دەگرێتەوە و بابەتە وردترەکانی ڕێزمان لە کوێ دەخوێندرێنەوە؟</li></ol></section>
<section class="klesson-card"><h2>٥. چوار یەکی جیاواز: زمان، ئەلفبێ، ڕێنووس و شێوەزار</h2>
<p>بۆ خوێندنەوەی زانستیی کورمانجی، ئەم چەمکانە دەبێت لە یەکدی جیا بکرێنەوە:</p>
<ul>
<li><strong>زمان و شێوەی زمانی:</strong> کورمانجی بە شێوەیەکی گشتی وەک یەکێک لە ڕێڕەوە سەرەکییەکانی کوردی باس دەکرێت؛ بەڵام لە ناوچە و کۆمەڵگە جیاوازەکاندا تایبەتمەندیی دەنگی، وشەسازی و بەکارهێنان هەیە.</li>
<li><strong>ئەلفبێ:</strong> کۆمەڵە پیت و نیشانەیەکە کە بۆ نوسین بەکاردێت. ئەلفبێی لاتینیی هاوار ڕێکخستنێکی باوی نووسینی کورمانجییە.</li>
<li><strong>ڕێنووس:</strong> ڕێسای هەڵبژاردن و ڕیزکردنی پیتەکان لە وشەی نووسراودا؛ بۆیە نیشانەیەکی وەک <em>ç</em> نابێت بە بێ پشکنین لە <em>c</em> بگۆڕدرێت.</li>
<li><strong>دەنگ و دەنگناسی:</strong> دەنگەکان پەیوەندییان بە شێوەی دەربڕین و جیاوازییە دەنگییەکانەوە هەیە. پیت و دەنگ پەیوەستن، بەڵام یەک چەمک نین.</li>
</ul>
<p class="klesson-note">بەڵگەی زمان‌ناسی: Haig (2018) ڕێنووسی نووسراوی باوی کورمانجی لەگەڵ جیاوازیی ناوچەیی باس دەکات. بۆیە لەم کۆرسەدا ڕێنووسی ستانداردی بەکارهاتوو دەناسێنین، بەڵام جیاوازییە زمانییەکان بە هەڵە وەک «هەڵەی ڕێنووس» ناناسێنین، مەگەر سەرچاوەی دیاریکراو پشتگیری بکات.</p>
</section>
<section class="klesson-card"><h2>٦. چۆنیەتی خوێندنەوەی نمونە</h2>
<p>نمونەی <em>Kurmancî</em> ناوی ئەم شێوە زمانییە بە شێوەی نووسینی لاتینی پیشان دەدات؛ <em>Kurdî</em> فۆڕمی نووسینی وشەی «کوردی»یە. لە وشەکانی <em>çav</em> («چاو») و <em>şev</em> («شەو»)دا، پیتی نیشانەدارەکانی <em>ç</em> و <em>ş</em> بەشێکن لە ڕێنووسی وشەکە، نەک ڕازاندنەوەی تایپۆگرافی.</p>
<p>کاتی شیکردنەوەی هەر نمونەیەک، ئەم زانیارییانە تۆمار بکە: فۆڕمی نووسراو، واتا، جۆری پیتە گرنگەکان، سەرچاوەی نمونەکە، و ئەوەی نمونەکە بۆ ڕێنووسی ستانداردە یان بۆ شێوەزارێکی دیاریکراوە.</p>
<table class="klesson-table"><thead><tr><th>نمونە</th><th>تێبینیی ڕێنووسی</th><th>مەبەستی فێربون</th></tr></thead><tbody>
<tr><td><em>Kurmancî</em></td><td>پیتی <em>î</em> لە کۆتایی ناوەکەدا هەیە</td><td>پاراستنی نیشانەی پیت</td></tr>
<tr><td><em>Kurdî</em></td><td><em>î</em> لە کۆتایی وشەکەدا هەیە</td><td>جیاکردنەوەی فۆڕمی نووسراو لە شێوەی نیشانەبێ</td></tr>
<tr><td><em>çav</em></td><td><em>ç</em> پیتێکی سەربەخۆی ئەلفبێیە</td><td>تێبینیی جیاوازیی <em>c</em> و <em>ç</em></td></tr>
<tr><td><em>şev</em></td><td><em>ş</em> پیتێکی سەربەخۆی ئەلفبێیە</td><td>تێبینیی جیاوازیی <em>s</em> و <em>ş</em></td></tr>
</tbody></table>
<p class="klesson-note">ئەم نمونانە بۆ ڕاهێنانی سەرەتاییی ڕێنووسن. لە وانەکانی دواتردا سیستەمی ڤاوڵ، کۆنسۆنانت و پەیوەندیی پیت و دەنگ بە وردیتر دەخوێندرێنەوە؛ لێرەدا لە پێشدا بڕیارێکی دەنگناسیی ورد لەسەر هەر پیتێک نادرێت.</p>
</section>
<section class="klesson-card"><h2>٧. ڕاهێنانی شیکاری</h2>
<ol><li>بە وشەی خۆت جیاوازیی نێوان ئەلفبێ و ڕێنووس ڕوون بکەرەوە.</li><li>لە <em>çav</em> و <em>şev</em>دا کام پیتەکان نابێت لە نووسینی فەرمی بسڕدرێنەوە یان بگۆڕدرێن؟</li><li>ئەگەر لە سەرچاوەیەکدا فۆڕمێکی ناوچەیی ببینیت کە لە ڕێنووسی ستاندارد جیاوازە، پێش ئەوەی بە هەڵە دایبنێیت چ زانیارییەکت پێویستە؟</li><li>بۆ یەک وشە، خشتەیەک دروست بکە کە فۆڕمی نووسراو، واتا، سەرچاوە و تێبینیی شێوەزاری تێدا بێت.</li></ol>
</section>
<section class="klesson-card"><h2>تێبینیی مێتۆدی</h2>
<p>لە وانەیەکی ئەکادێمیکدا، سەرچاوە تەنها لیستی کتێب نیە: دەبێت ڕوون بێت کام بەش یان خشتە پشتگیریی ئەو یاسا یان نمونەیە دەکات. لەو شوێنانەی لاپەڕە یان بەش پشتڕاست نەکراوەتەوە، نابێت ژمارەی لاپەڕە بە خەمڵاندن زیاد بکرێت. هەر زیادکردنێکی داهاتووی نمونەی زمانەوانی دەبێت بە سەرچاوەیەکی دیاریکراو و بە پاراستنی فۆڕمی لاتینیی ڕەسەن بکرێت.</p>
</section>
<section class="klesson-card"><h2>سەرچاوەکان</h2><ol><li>Haig, Geoffrey. (2018). “Northern Kurdish (Kurmanjî).” In Geoffrey Haig & Geoffrey Khan (eds.), <em>The Languages and Linguistics of Western Asia: An Areal Perspective</em>, pp. 106–158. Berlin: De Gruyter Mouton. <a href="https://doi.org/10.1515/9783110421682-004" target="_blank" rel="noopener">DOI: 10.1515/9783110421682-004</a>.</li><li>Thackston, W. M. (2006). <em>Kurmanji Kurdish: A Reference Grammar with Selected Readings</em>. سەرچاوەی ڕێزمان و خوێندنەوەی کورمانجی.</li><li>Haig, Geoffrey &amp; Ergin Öpengin. (2018). “Kurmanjî Kurdish in Turkey: Structure, varieties, and status.” In Christiane Bulut (ed.), <em>Linguistic Minorities in Turkey and Turkic-speaking Minorities of the Peripheries</em>, pp. 157–230. Harrassowitz. <a href="https://fis.uni-bamberg.de/handle/uniba/45103" target="_blank" rel="noopener">زانیاریی کتێبناسی لە زانکۆی بامبێرگ</a>.</li></ol><p class="klesson-note">سەرچاوەکان چوارچێوەی گشتیی زمان، ڕێنووس و جیاوازیی ناوچەیی پشتگیری دەکەن؛ بەڵام پێش بڵاوکردنەوەی کۆتایی، دەبێت هەر نمونەیەکی ورد بە چاپ و بەشی پەیوەندیداری سەرچاوەکەوە بگونجێندرێت. ژمارەی لاپەڕەی نەپشکنراو بە خەمڵاندن زیاد نەکراوە.</p></section>',now()),
    ('kurmanji-course-1-lesson-02.html','kurmanji-course-1','ئەلفبێی هاوار و ٣١ پیتەکەی','<section class="klesson-card"><h2>١. ڕیزبەندی ئەلفبێ</h2><p>لە ڕێنووسی لاتینیی باوی کورمانجی، ئەلفبێکە ٣١ پیت لەخۆ دەگرێت. ئەم ڕیزبەندییە بۆ ناسینەوە و ڕێکخستنی وشەکان گرنگە:</p><div class="klesson-alphabet" aria-label="ئەلفبێی کورمانجی"><span>A</span><span>B</span><span>C</span><span>Ç</span><span>D</span><span>E</span><span>Ê</span><span>F</span><span>G</span><span>H</span><span>I</span><span>Î</span><span>J</span><span>K</span><span>L</span><span>M</span><span>N</span><span>O</span><span>P</span><span>Q</span><span>R</span><span>S</span><span>Ş</span><span>T</span><span>U</span><span>Û</span><span>V</span><span>W</span><span>X</span><span>Y</span><span>Z</span></div><p class="klesson-note">تێبینی: پیتەکانی ئەم ئەلفبێیە بە ڕێنووسی لاتینیی کورمانجی پەیوەستن. نابێت نیشانەی پیتەکان لە نوسینی کوردی بە ئەلفبێی عەرەبی یان لە سیستەمەکانی دیکەدا بە هەمان شێوە لێک بدرێنەوە.</p></section>
<section class="klesson-card"><h2>٢. پیتەکانی نیشانەدار</h2><ul><li><strong>Ç / ç</strong></li><li><strong>Ê / ê</strong></li><li><strong>Î / î</strong></li><li><strong>Ş / ş</strong></li><li><strong>Û / û</strong></li></ul><p>ئەم نیشانانە بەشێکن لە شێوەی نوسینی پیتەکە؛ لە نوسینی فەرمی‌دا نابێت بە پیتی بێ‌نیشانە بگۆڕدرێن، چونکە جیاوازیی ڕێنووسی دەهێننە ئاراوە. پیتەکانی Q، W و Xیش لە ئەلفبێی لاتینیی کورمانجی بەکاردێن.</p></section>
<section class="klesson-card"><h2>٣. پیت و دەنگ یەک شت نین</h2><p>پیت نیشانەی نوسراوە؛ دەنگ ئەو یەکەیە کە لە قسەکردندا دەبیسترێت. پەیوەندیی نێوان پیت و دەنگ بابەتێکی گرنگی فێربونی ڕێنووسە، بەڵام نابێت بە بێ پشکنینی دەنگییەوە وا دابنرێت کە هەر پیتێک لە هەمو وشە و شێوەزارێکدا تەنیا یەک دەنگی هەیە.</p></section>
<section class="klesson-card"><h2>٤. ڕاهێنان</h2><ol><li>ئەلفبێکە بە ڕیزبەندییەوە بخوێنەوە و بنووسە.</li><li>پیتە نیشانەدارەکان لە لیستەکەدا دیاری بکە.</li><li>بۆچی Ç و C، یان Ş و S، لە نوسینی فەرمی‌دا نابێت بە یەک شت دابنرێن؟</li></ol></section>
<section class="klesson-card"><h2>٥. پۆلێنکردنی پیتەکان: ڤاوڵ و کۆنسۆنانت</h2>
<p>لە ئەلفبێی لاتینیی کورمانجی، ٣١ پیت هەیە. لە پۆلێنکردنی سەرەتاییدا، ٨ پیت بە ڤاوڵ دادەنرێن: <em>A, E, Ê, I, Î, O, U, Û</em>؛ ٢٣ پیتەکەی دیکە کۆنسۆنانتن. ئەم پۆلێنکردنە بۆ فێربونی سیستەمی دەنگی گرنگە، بەڵام خۆی بە تەنیا هەمو تایبەتمەندیی دەنگیی وشەکان ڕوون ناکاتەوە.</p>
<table class="klesson-table"><thead><tr><th>گروپ</th><th>پیتەکان</th><th>ئەرکی فێربون</th></tr></thead><tbody>
<tr><td>ڤاوڵ</td><td><em>A E Ê I Î O U Û</em></td><td>ناسینەوەی هەشت پیتی ڤاوڵ و پاراستنی نیشانەکانیان</td></tr>
<tr><td>کۆنسۆنانت</td><td><em>B C Ç D F G H J K L M N P Q R S Ş T V W X Y Z</em></td><td>ناسینەوەی ٢٣ پیتی کۆنسۆنانت و ڕیزبەندییان</td></tr>
</tbody></table>
<p class="klesson-note">ئەمە پۆلێنکردنێکی ئەلفبێییە. بۆ دیاریکردنی شوێنی دەربڕین، شێوەی دەربڕین یان جیاوازیی فۆنێمی، پێویستە بەڵگەی دەنگناسیی تایبەت بە وشە و شێوەزاری دیاریکراو بەکاربهێنرێت.</p>
</section>
<section class="klesson-card"><h2>٦. پیتە نیشانەدارەکان و هەڵەی گۆڕینی نووسین</h2>
<p>لە ئەلفبێی کورمانجی، <em>Ç/ç</em>، <em>Ê/ê</em>، <em>Î/î</em>، <em>Ş/ş</em> و <em>Û/û</em> پیتە جیاوازەکانن. نیشانەی سەر پیت بەشێکە لە فۆڕمی نووسراوەکە؛ نابێت لە کاتی کۆپی‌کردن، گەڕان، نوسینی داتابەیس یان دروستکردنی فهرستدا بەبێ هۆکار بسڕدرێتەوە.</p>
<ul><li><strong>پاراستنی فۆڕم:</strong> فۆڕمی <em>şev</em> بە <em>sev</em> یەکسان نیە لە ڕووی ڕێنووسەوە.</li><li><strong>جیاوازیی پیت:</strong> <em>c</em> و <em>ç</em> نابێت بە یەک پیت دابنرێن؛ هەمان شت بۆ <em>s</em> و <em>ş</em>یش ڕاستە.</li><li><strong>پیتی گەورە و بچووک:</strong> <em>Ç/ç</em> و <em>Ş/ş</em> دوو شێوەی هەمان پیتن، بەڵام ئەمە بە مانای یەکسانبوونیان لەگەڵ <em>C/c</em> و <em>S/s</em> نیە.</li></ul>
<p class="klesson-note">لە سیستەمی دیجیتاڵدا، بۆ بەراوردکردنی دەقی ڕەسەن پێویستە فۆڕمی پیتەکان بپارێزرێت. گەڕانێک کە نیشانەکان لادەبات دەتوانێت بۆ ئاسانکاریی گەڕان بەکاربهێنرێت، بەڵام نابێت دەقی ڕەسەن بگۆڕێت یان جێگای نووسینی دروست بگرێتەوە.</p>
</section>
<section class="klesson-card"><h2>٧. ڕیزبەندی و فهرستکردنی وشە</h2>
<p>ڕیزبەندیی ئەلفبێ تەنها بۆ لەبەرکردنی پیتەکان نیە؛ لە فهرستی وشە، فەرهەنگ، کتێب‌خانە و گەڕانی دیجیتاڵدا بەکاردێت. کاتێک دوو وشە بە پیتە سەرەتاییەکاندا هاوشێوەن، پیتەکانی دواتر لە دیاریکردنی شوێنیاندا گرنگ دەبن. لە هەمان کاتدا، پیتە نیشانەدارەکان دەبێت بەپێی ڕێسای ڕیزبەندیی سیستەمەکە مامەڵەیان لەگەڵ بکرێت، نەک بە خەمڵاندن.</p>
<ol><li>ئەلفبێی ٣١ پیتی لە سەرەتاوە بنووسە و پیتە نیشانەدارەکان بە جیا نیشان بکە.</li><li>لە فهرستێکی خەیاڵیدا وشەکان بە پیتی یەکەم ڕیز بکە؛ دواتر وشە هاوشێوەکان بە پیتی دووەم جیا بکەرەوە.</li><li>ڕوون بکەرەوە بۆچی گۆڕینی <em>ş</em> بۆ <em>s</em> دەتوانێت لە گەڕان یان فهرستکردندا کێشە دروست بکات.</li></ol>
</section>
<section class="klesson-card"><h2>٨. ڕاهێنانی پشکنینی زانستی</h2>
<ol><li>ژمارەی پیتەکانی ئەلفبێ بنووسە و ژمارەی ڤاوڵ و کۆنسۆنانتەکان بە جیا دیاری بکە.</li><li>پیتە نیشانەدارەکان بنووسە و بۆ هەر یەکێک شێوەی گەورە و بچووکی بنووسە.</li><li>بە وشەی خۆت جیاوازیی نێوان پیت و دەنگ ڕوون بکەرەوە.</li><li>بۆچی نابێت لە کاتی ڕێکخستنی دەقی لاتینیی کورمانجی نیشانەکانی پیتەکان بە شێوەی ئۆتۆماتیکی بسڕدرێنەوە؟</li><li>ئەگەر فهرستێک پیتە نیشانەدارەکان لەبەرچاو نەگرێت، چ جۆرە هەڵەیەک لە دۆزینەوەی وشەکاندا ڕوودەدات؟</li></ol>
</section>
<section class="klesson-card"><h2>تێبینیی مێتۆدی</h2>
<p>ژمارەی پیتەکان و ڕیزبەندیی ئەلفبێ بە ئاسانی دەتوانرێت بە لیستی فەرمیی ئەلفبێ بپشکنرێت؛ بەڵام بانگەشەی دەنگناسیی ورد پێویستی بە سەرچاوەی دەنگناسی و نمونەی پشتڕاستکراوە هەیە. لەم وانەیەدا نمونەکان بۆ فێربونی پیت و ڕێنووسن، نەک بۆ دیاریکردنی تەواوی سیستەمی فۆنۆلۆژی.</p>
</section>
<section class="klesson-card"><h2>سەرچاوەکان</h2><ol><li>Haig, Geoffrey. (2018). “Northern Kurdish (Kurmanjî).” In Geoffrey Haig & Geoffrey Khan (eds.), <em>The Languages and Linguistics of Western Asia: An Areal Perspective</em>, pp. 106–158. De Gruyter Mouton. <a href="https://doi.org/10.1515/9783110421682-004" target="_blank" rel="noopener">DOI: 10.1515/9783110421682-004</a>.</li><li>Thackston, W. M. (2006). <em>Kurmanji Kurdish: A Reference Grammar with Selected Readings</em>. Harvard University.</li><li>University of Arizona, Iranian Languages. <a href="https://iranian-languages.arizona.edu/node/7" target="_blank" rel="noopener">Kurmanji Kurdish</a>.</li></ol><p class="klesson-note">سەرچاوەکان بۆ چوارچێوەی گشتیی زمان و ڕێنووس دانراون. بۆ وەشانی کۆتایی، دەبێت هەر نمونەیەکی ورد بە چاپی سەرچاوەی ڕێنووسەکەوە بگونجێندرێت.</p></section>',now()),
    ('kurmanji-course-1-lesson-03.html','kurmanji-course-1','ڤاوڵەکان و نیشانەنووسییان','<section class="klesson-card"><h2>١. هەشت پیتی ڤاوڵ و هاوتاکانیان لە IPA</h2>
<p>لە ڕێنووسی لاتینیی باوی کورمانجی، هەشت پیتی ڤاوڵ بۆ نوێنەرایەتیی هەشت مۆنۆفتۆنگی سەرەکی بەکاردێن. خشتەی خوارەوە فۆڕمی نووسراو، نیشانەی دەنگناسیی نێودەوڵەتی (IPA)، نمونە و واتای ئینگلیزیی سەرچاوەکە نیشان دەدات. IPA وەسفی دەنگە، نەک پیتی ئەلفبێ.</p>
<table class="klesson-table"><thead><tr><th>پیت</th><th>IPA</th><th>نمونە</th><th>واتا</th></tr></thead><tbody>
<tr><td>A a</td><td>/ɑ/</td><td>qaz</td><td>قاز / goose</td></tr>
<tr><td>E e</td><td>/æ/</td><td>belg</td><td>گەڵا / leaf</td></tr>
<tr><td>Ê ê</td><td>/e/</td><td>lêv</td><td>لێو / lip</td></tr>
<tr><td>I i</td><td>/ɪ/</td><td>dil</td><td>دڵ / heart</td></tr>
<tr><td>Î î</td><td>/i/</td><td>hîn</td><td>هێشتا / still</td></tr>
<tr><td>O o</td><td>/o/</td><td>nod</td><td>نەوەد / ninety</td></tr>
<tr><td>U u</td><td>/ʊ/</td><td>qul</td><td>کون / hole</td></tr>
<tr><td>Û û</td><td>/u/</td><td>bûz</td><td>سەهۆڵ / ice</td></tr>
</tbody></table>
<p class="klesson-note">IPA و واتاکانی ئینگلیزی لە خشتەی دەنگناسیی پەڕەی Iranian Languages ـی زانکۆی ئەریزۆنا وەرگیراون. وەرگێڕانی کوردیی واتاکان بۆ یارمەتیی فێرخواز زیاد کراوە؛ ئەگەر لە فەرهەنگ یان شێوەزارێکدا فۆڕمی جیاواز هەبێت، پێویستە بە سەرچاوەی تایبەت پشتڕاست بکرێتەوە.</p></section>
<section class="klesson-card"><h2>٢. نیشانەی پیت بەشێکە لە ڕێنووس</h2>
<p>لە نووسینی کورمانجی، <strong>e</strong> و <strong>ê</strong>، <strong>i</strong> و <strong>î</strong>، هەروەها <strong>u</strong> و <strong>û</strong> پیتە جیاوازن و لە خشتەی دەنگناسیشدا بە IPAی جیاواز نیشان دەدرێن. نیشانەی چەرخەک (circumflex) لە <em>ê, î, û</em> بەشێکە لە فۆڕمی پیتەکە؛ نابێت لە کاتی نووسین، کۆپی‌کردن یان فهرستکردندا بەبێ هۆکار بسڕدرێتەوە.</p>
<p>خشتەی زانکۆی ئەریزۆنا بۆ ئەم هەشت ڤاوڵە بە ڕیزبەندییەکی دیاریکراو IPA بەکاردهێنێت: <em>a /ɑ/، e /æ/، ê /e/، i /ɪ/، î /i/، o /o/، u /ʊ/، û /u/</em>. ئەم نیشانەکانە وەسفی سیستەمی گشتیی ڕێنووس و دەنگن؛ نابێت لەوەوە وا تێبگەین کە وردەکاریی دەربڕین لە هەمو ناوچە و قسەکەرێکدا یەکسانە.</p></section>
<section class="klesson-card"><h2>٣. جیاوازیی شێوەزار و ڕێبازی خوێندنەوە</h2>
<p>پەڕەی زانکۆی ئەریزۆنا تێبینی دەکات کە ڤاوڵی نووسراو بە <em>e</em> کە بە /æ/ نیشان دەدرێت، لە هەندێک شێوەزاردا دەتوانێت هەڵگری دەربڕینی نزیک لە /ə/ یان /ɛ/ بێت؛ بۆ زۆر قسەکەر دەربڕینەکە لە هەمو ژینگەکاندا نزیکترە لە /ɛ/. بۆیە IPA لێرەدا وەسفێکی ڕێنووس-دەنگیی گشتییە، نەک یاسایەکی بێ‌جیاوازی بۆ هەمو شێوەزارەکان.</p>
<p>کاتی فێربون، وشەکە بە نووسینی ڕەسەن بخوێنەوە، پیتی ڤاوڵ دیاری بکە، و تەنیا کاتێک کە سەرچاوەی دەنگی بەردەستە بڕیار لەسەر وردەکاریی دەربڕین بدە. هاوتاکردنەوەی دەنگەکان بە دەنگی ئینگلیزی یان کوردیی ناوەندی تەنیا ڕێنماییەکی نزیکە، نەک جێگرەوەی سەرچاوەی دەنگناسی.</p></section>
<section class="klesson-card"><h2>٤. ڕاهێنانی شیکاری</h2><ol>
<li>هەشت پیتی ڤاوڵ بە پیتی گەورە و بچووک بنووسە.</li>
<li>لە خشتەکەدا e/ê، i/î و u/û بە بەراوردی IPA جیا بکەرەوە.</li>
<li>وشەکانی <em>qaz, belg, lêv, dil, hîn, nod, qul, bûz</em> بخوێنەوە و پیتی ڤاوڵی هەر یەک دیاری بکە.</li>
<li>بۆچی ناتوانین بە تەنیا لەسەر پیتی نووسراو بڕیار بدەین کە دەربڕینی هەمو قسەکەرێک بە تەواوی یەکسانە؟ بە تێبینیی سەرچاوە و جیاوازیی ناوچەیی وەڵام بدەوە.</li>
<li>لە کۆپی‌کردنی وشەکاندا نیشانەکانی <em>ê, î, û</em> بپارێزە و پاشان فۆڕمی نووسراو لەگەڵ سەرچاوەکە بەراورد بکە.</li>
</ol></section>
<section class="klesson-card"><h2>سەرچاوەکان</h2><ol>
<li>University of Arizona, Iranian Languages. <a href="https://iranian-languages.arizona.edu/node/7" target="_blank" rel="noopener">Kurmanji Kurdish — Phonology and Orthography</a> (خشتەی هەشت ڤاوڵ، IPA، نمونە و تێبینیی شێوەزار).</li>
<li>Haig, Geoffrey. (2018). “Northern Kurdish (Kurmanjî).” In Geoffrey Haig &amp; Geoffrey Khan (eds.), <em>The Languages and Linguistics of Western Asia: An Areal Perspective</em>, pp. 106–158. De Gruyter Mouton. <a href="https://doi.org/10.1515/9783110421682-004" target="_blank" rel="noopener">DOI</a>.</li>
<li>Thackston, W. M. (2006). <em>Kurmanji Kurdish: A Reference Grammar with Selected Readings</em>. Harvard University.</li>
</ol><p class="klesson-note">سەرچاوەی زانکۆی ئەریزۆنا بۆ نمونە و IPA بە شێوەی ڕاستەوخۆ پشکنراوە. ئەم وانەیە پێشەکییە بۆ ڤاوڵەکان؛ وردەکاریی فۆنۆلۆژی و جیاوازیی شێوەزارەکان لە پێویستیدا دەبێت لە سەرچاوەی تایبەتیانەوە بخوێندرێنەوە.</p></section>',now()),
    ('kurmanji-course-1-lesson-04.html','kurmanji-course-1','کۆنسۆنەنتەکان و پەیوەندییان بە نوسینەوە','<section class="klesson-card"><h2>١. کۆنسۆنەنت چیە؟</h2>
<p>کۆنسۆنەنت (consonant) دەنگێکە کە لە دروستبوونیدا هەوا لە ڕێگای دەمداندا بە تەنگەبەر یان بەربەستێک ڕووبەڕوو دەبێتەوە. لە زانستی زماندا دەبێت جیاوازی بکەین لە نێوان <strong>پیت</strong>، کە نیشانەیەکی نووسراوە، و <strong>فونیم</strong>، کە یەکەیەکی دەنگییە و دەتوانێت واتای وشە جیا بکاتەوە. بۆیە خشتەی ئەلفبێ بە تەنیا هەمو جیاوازییە دەنگییەکانی کورمانجی نیشان نادات.</p>
<p>لە ڕێنووسی لاتینیی ستاندارددا ٢٣ پیتی کۆنسۆنەنت هەن؛ بەڵام لە پەڕەی دەنگناسیی زانکۆی ئەریزۆنا تێبینی کراوە کە ژمارە و جۆری جیاوازیی دەنگی بە پێی شێوەزار دەتوانێت بگۆڕێت. بۆ خوێندنەوەی ورد، نیشانەکانی IPA بەکاربهێنە و جیاوازیی ناوچەیی لەبەرچاو بگرە.</p></section>
<section class="klesson-card"><h2>٢. پیتە کۆنسۆنەنتەکان و IPA</h2>
<p>ئەم خشتەیە پەیوەندیی گشتیی نێوان پیت و دەنگی نوێنەرایەتی‌کراویان نیشان دەدات. IPA وەسفی دەنگە؛ نابێت بە پیتی لاتینی تێکەڵ بکرێت.</p>
<table class="klesson-table"><thead><tr><th>پیت</th><th>IPAی گشتی</th><th>تێبینی</th></tr></thead><tbody>
<tr><td>B b</td><td>/b/</td><td>وەستانی دەنگدار</td></tr>
<tr><td>C c</td><td>/d͡ʒ/</td><td>دەنگی تێکەڵەی وەستان و سایش</td></tr>
<tr><td>Ç ç</td><td>/t͡ʃ/</td><td>هاوتای بێ‌دەنگی C لە خشتەی گشتی</td></tr>
<tr><td>D d</td><td>/d/</td><td>وەستانی دەنگدار</td></tr>
<tr><td>F f</td><td>/f/</td><td>سایشدار</td></tr>
<tr><td>G g</td><td>/g/</td><td>وەستانی دەنگدار</td></tr>
<tr><td>H h</td><td>/h/</td><td>سایشدار</td></tr>
<tr><td>J j</td><td>/ʒ/</td><td>وەک دەنگی ناوەڕاستی وشەی ژ لە زۆر وەسفەکاندا</td></tr>
<tr><td>K k</td><td>/k/</td><td>وەستانی بێ‌دەنگ</td></tr>
<tr><td>L l</td><td>/l/</td><td>نزیکەدەنگی لایەنی</td></tr>
<tr><td>M m</td><td>/m/</td><td>لووتی</td></tr>
<tr><td>N n</td><td>/n/</td><td>لووتی</td></tr>
<tr><td>P p</td><td>/p/</td><td>وەستانی بێ‌دەنگ</td></tr>
<tr><td>Q q</td><td>/q/</td><td>وەستانی لووتکەیی</td></tr>
<tr><td>R r</td><td>/ɾ/</td><td>tap/flap؛ لە زۆر وەسفەکاندا</td></tr>
<tr><td>RR rr (دووپیت، نەک پیتی سەربەخۆ)</td><td>/r/</td><td>trill؛ جیاوازییەکە لە هەمو شێوەزار و شێوەنووسێکدا بە یەک شێوە نانووسرێت</td></tr>
<tr><td>S s</td><td>/s/</td><td>سایشدار</td></tr>
<tr><td>Ş ş</td><td>/ʃ/</td><td>سایشدار؛ جیاوازە لە S</td></tr>
<tr><td>T t</td><td>/t/</td><td>وەستانی بێ‌دەنگ</td></tr>
<tr><td>V v</td><td>/v/</td><td>سایشدار</td></tr>
<tr><td>W w</td><td>/w/</td><td>نزیکەدەنگی لێو-کامی</td></tr>
<tr><td>X x</td><td>/χ/؛ لە هەندێک شێوەزار /ʁ/</td><td>هەردوو دەنگەکە لە ڕێنووسی ستاندارددا بە X نووسراون</td></tr>
<tr><td>Y y</td><td>/j/</td><td>نزیکەدەنگی کامی</td></tr>
<tr><td>Z z</td><td>/z/</td><td>سایشداری دەنگدار</td></tr>
</tbody></table>
<p class="klesson-note">ئەمە خشتەی پێشەکیی پیتەکانە، نەک تۆماری تەواوی وردەکاریی دەنگناسی. سەرچاوەکە جیاوازیی /r/ و /ɾ/، هەروەها جیاوازییەکانی aspirated/unaspirated و دەنگەکانی /χ/ و /ʁ/ بۆ هەندێک شێوەزار باس دەکات.</p></section>
<section class="klesson-card"><h2>٣. پیت و دەنگ هەمیشە یەک‌بەیەک ناگونجێن</h2>
<ul>
<li><strong>C / Ç:</strong> لە خشتەی گشتیی IPAدا C بە /d͡ʒ/ و Ç بە /t͡ʃ/ نوێنەرایەتی دەکرێن؛ نیشانەی چەسپاو لە Ç بەشێکە لە پیتەکە.</li>
<li><strong>S / Ş:</strong> /s/ و /ʃ/ دوو دەنگی جیاوازن؛ لابردنی نیشانەی Ş دەکرێت ڕێنووس و خوێندنەوە بگۆڕێت.</li>
<li><strong>R / RR:</strong> لە وەسفی گشتیی زانکۆی ئەریزۆنا، /ɾ/ دەنگی tap/flap و /r/ دەنگی trill ـە؛ لە هەندێک شێوەی نووسین، RR جیاوازیی trill نیشان دەدات، بەڵام ڕێنووس لە هەمو شوێنێکدا ئەم جیاوازییە بە یەک شێوە نانووسێت.</li>
<li><strong>K, P, T و Ç:</strong> لە هەندێک شێوەزاردا جیاوازیی دەنگی لە نێوان بێ‌هەناسە/کەم‌هەناسە و پڕهەناسە هەیە؛ زۆرجار ڕێنووسی لاتینیی ستاندارد ئەم جیاوازییە بە نیشانەی تایبەت نانووسێت.</li>
<li><strong>X:</strong> لە ڕێنووسی ستاندارددا X پیتی سەربەخۆیە؛ لە سەرچاوەکەدا /χ/ و /ʁ/ هەردووکیان لە هەندێک شێوەزاردا بە X نووسراون، بۆیە نابێت هەمیشە تەنیا یەک دەنگ بۆی دابنرێت.</li>
</ul></section>
<section class="klesson-card"><h2>٤. ڕاهێنانی شیکاری</h2>
<ol>
<li>لە خشتەکەدا پیتەکانی C، Ç، S، Ş و X بدۆزەوە و IPAی هەر یەک بنووسە.</li>
<li>بە دوو ڕستە ڕون بکەرەوە بۆچی پیت و فونیم یەک شت نین.</li>
<li>جیاوازیی /ɾ/ و /r/ دیاری بکە و ڕون بکەرەوە بۆچی نووسینی RR لە هەمو شێوەزارێکدا بە یەک شێوە بەکارناهێنرێت.</li>
<li>بە پشت‌بەستن بە سەرچاوەکە، بڵێ بۆچی ناتوانین لەسەر بنەمای ڕێنووس تەنیا بڕیار بدەین کە جیاوازیی aspirated/unaspirated لە هەمو شێوەزارەکاندا هەیە.</li>
<li>وشەیەک کە Ç یان Şی تێدایە لە سەرچاوەی فێرکارییەکەت هەڵبژێرە و پیتەکە بە نیشانەی ڕەسەنی خۆی بنووسە.</li>
</ol></section>
<section class="klesson-card"><h2>سەرچاوەکان</h2>
<ol>
<li>University of Arizona, Iranian Languages. <a href="https://iranian-languages.arizona.edu/node/7" target="_blank" rel="noopener">Kurmanji Kurdish — Phonology and Orthography</a> (خشتەی IPA و تێبینیی شێوەزارەکان).</li>
<li>Haig, Geoffrey. (2018). “Northern Kurdish (Kurmanjî).” In Geoffrey Haig &amp; Geoffrey Khan (eds.), <em>The Languages and Linguistics of Western Asia: An Areal Perspective</em>, pp. 106–158. De Gruyter Mouton. <a href="https://doi.org/10.1515/9783110421682-004" target="_blank" rel="noopener">DOI</a>.</li>
<li>Thackston, W. M. (2006). <em>Kurmanji Kurdish: A Reference Grammar with Selected Readings</em>. Harvard University.</li>
</ol><p class="klesson-note">سەرچاوەی زانکۆی ئەریزۆنا سەرچاوەی سەرەکیی ئەم خشتەیەیە. لەوانەیە ڕێنووس یان وردەکاریی دەربڕین لە شێوەزارێکەوە بۆ شێوەزارێکی دیکە جیاواز بێت؛ لە کاتی تێبینیی شێوەزاردا دەبێت ناوچە و سەرچاوەکە دیاری بکرێن.</p></section>',now()),
    ('kurmanji-course-1-lesson-05.html','kurmanji-course-1','پیتە تایبەتەکان: ç، ş، ê، î، û','<section class="klesson-card"><h2>١. پێنج پیتەکە</h2><p>ئەلفبێی لاتینیی کورمانجی ٣١ پیتی هەیە. پێنج پیتی نیشانەدار بریتین لە <strong>ç، ş، ê، î، û</strong>؛ ئەم نیشانانە جوانکاری نین، بەڵکو بەشێکن لە شێوەی فەرمیی پیتەکە و دەبێت لە نوسین و خوێندنەوەدا بپارێزرێن.</p><p><strong>جیاوازیی شێوە و ئەرک:</strong> <em>ç</em> و <em>ş</em> کۆنسۆنەنتن؛ <em>ê</em>، <em>î</em> و <em>û</em> ڤاوڵن. نیشانەی ژێرەوەی ç/ş (cedilla) و هێمای سەرەوەی ê/î/û (circumflex) لە فۆڕمی پیتەکە جیاوازی دروست دەکەن، نەک تەنها لە شێوازی جوانکاری.</p><table class="klesson-table"><thead><tr><th>پیت</th><th>نمونەی کورمانجی</th><th>واتا</th><th>تێبینی</th></tr></thead><tbody>
<tr><td>ç</td><td>çak</td><td>باش</td><td>لە خشتەی زانکۆی ئەریزۆنا بە /t͡ʃ/ نوێنەرایەتی دەکرێت.</td></tr>
<tr><td>ş</td><td>şaş</td><td>هەڵە</td><td>/ʃ/؛ پیتی ş لە s جیاوازە.</td></tr>
<tr><td>ê</td><td>êş</td><td>ئازار</td><td>ڤاوڵێکی جیاواز لە e.</td></tr>
<tr><td>î</td><td>îro</td><td>ئەمڕۆ</td><td>ڤاوڵێکی جیاواز لە i.</td></tr>
<tr><td>û</td><td>bûz</td><td>سەهۆڵ</td><td>ڤاوڵێکی جیاواز لە u.</td></tr></tbody></table>
<p class="klesson-note">نمونە و واتاکان لە خشتەی ڕێنووس و دەنگناسیی کورمانجیی زانکۆی ئەریزۆنا وەردەگیرێن. دەربڕینی وردی دەنگەکان دەتوانێت بە شێوەزار بگۆڕێت؛ بۆیە ئەم وانەیە بنەمای نوسین دەخاتەڕوو، نەک هەمو جیاوازییە دەنگییەکان.</p></section>
<section class="klesson-card"><h2>٢. نیشانەکە لە نوسین دابمەزرێنە</h2><ul><li><strong>ç</strong> هەمیشە لە نوسین لە <strong>c</strong> جیاوازە؛ لەبیرت نەچێت نیشانەکە لاببەیت.</li><li><strong>ş</strong> لە <strong>s</strong> جیاوازە؛ نوسینی şaş بە شێوەی sash یان sas هەمان ڕێنووس نیە.</li><li><strong>ê</strong> لە <strong>e</strong>، <strong>î</strong> لە <strong>i</strong>، و <strong>û</strong> لە <strong>u</strong> جیاوازن. نیشانەی پیتەکە بە وردی بنووسە.</li><li>لە پیتی گەورەدا شێوەکان بریتین لە <strong>Ç، Ş، Ê، Î، Û</strong>.</li></ul></section>
<section class="klesson-card"><h2>٣. ڕاهێنانی نوسین</h2><ol><li>هەر پیتێک پێنج جار بە شێوەی گەورە و بچووک بنووسە: Ç ç، Ş ş، Ê ê، Î î، Û û.</li><li>ئەم وشانە لە ڕووی پیتە تایبەتەکەوە پۆلێن بکە: çak، şaş، êş، îro، bûz.</li><li>بە بێ گۆڕینی نیشانەکان، هەر وشەیەک لە خشتەکەوە دووبارە بنووسە.</li><li>بە وشەیەکی ڕاستەقینە لە سەرچاوەی فێرکاری، نمونەیەک بۆ ç و ş بدۆزەوە و لەگەڵ وانەکەدا تۆماری بکە.</li></ol></section>
<section class="klesson-card"><h2>سەرچاوەکان</h2><ol><li>University of Arizona, Iranian Languages. <a href="https://iranian-languages.arizona.edu/node/7" target="_blank" rel="noopener">Kurmanji Kurdish — Phonology and Orthography</a> (خشتەی پیت و نمونە وشەکان).</li><li>Haig, Geoffrey. (2018). “Northern Kurdish (Kurmanjî).” In Geoffrey Haig & Geoffrey Khan (eds.), <em>The Languages and Linguistics of Western Asia: An Areal Perspective</em>, pp. 106–158. De Gruyter Mouton. <a href="https://doi.org/10.1515/9783110421682-004" target="_blank" rel="noopener">DOI</a>.</li><li>Thackston, W. M. (2006). <em>Kurmanji Kurdish: A Reference Grammar with Selected Readings</em>. Harvard University.</li></ol></section>',now()),
    ('kurmanji-course-1-lesson-06.html','kurmanji-course-1','خوێندنەوە و نوسینی وشەی سادە','<section class="klesson-card"><h2>١. لە پیتەوە بۆ وشە</h2><p>خوێندنەوەی وشەی سادە بە ناسینی پیتەکان دەست پێدەکات، بەڵام پەیوەندیی پیت و دەنگ هەمیشە لە هەمو شێوەزارەکاندا یەکسان نیە. سەرەتا شێوەی نووسراو بە وردی ببینە، پاشان پیتەکان بناسەوە و بە پێی زانیاریی دەنگناسی وشەکە بخوێنەوە. لە کۆتاییدا واتاکە لە سەرچاوەیەکی باوەڕپێکراو بپشکنە.</p><ol><li>هەمو پیتەکان بە ڕیز بخوێنەوە و هیچ نیشانەیەک مەسڕەوە.</li><li>جیاوازیی <em>e/ê</em>، <em>i/î</em> و <em>u/û</em> بپارێزە.</li><li>پیتی سەربەخۆ وەک <em>ç</em>، <em>ş</em>، <em>q</em> و <em>x</em> بە پیتی تر مەگۆڕە.</li><li>ئەگەر دەنگێک لە شێوەزارێکدا جیاواز بوو، جیاوازیی دەنگی لە ڕێنووسی ستاندارد جیا بکەرەوە.</li></ol></section>
<section class="klesson-card"><h2>٢. وشەی سادە لەگەڵ ڕێنماییی دەنگی</h2><table class="klesson-table"><thead><tr><th>وشەی کورمانجی</th><th>واتا</th><th>تێبینیی خوێندنەوە</th></tr></thead><tbody>
<tr><td>av</td><td>ئاو</td><td>a = /ɑ/؛ v = /v/</td></tr>
<tr><td>dil</td><td>دڵ</td><td>i = /ɪ/؛ لە î جیاوازە</td></tr>
<tr><td>lêv</td><td>لێو</td><td>ê = /e/؛ نیشانەکە بپارێزە</td></tr>
<tr><td>hîn</td><td>هێشتا</td><td>î = /i/؛ لە i جیاوازە</td></tr>
<tr><td>qaz</td><td>قاز</td><td>a = /ɑ/؛ q پیتێکی جیاوازە</td></tr>
<tr><td>qul</td><td>کون</td><td>u = /ʊ/؛ لە û جیاوازە</td></tr>
<tr><td>çak</td><td>باش</td><td>ç = /t͡ʃ/؛ لە c جیاوازە</td></tr>
<tr><td>şaş</td><td>هەڵە</td><td>ş = /ʃ/؛ لە s جیاوازە</td></tr>
<tr><td>yek</td><td>یەک</td><td>y دەنگی /j/ نوێنەرایەتی دەکات</td></tr>
<tr><td>roj</td><td>ڕۆژ</td><td>وشەکە وەک نمونە بخوێنەوە؛ وردیی دەنگی r لە شێوەزارەکاندا دەتوانێت جیاواز بێت</td></tr>
</tbody></table><p class="klesson-note">IPA نیشانەی نێودەوڵەتیی دەنگە و پیت نیە. خشتەی زانکۆی ئەریزۆنا سەرچاوەی ڕاستەوخۆی واتا و بەرامبەرە دەنگییەکانی av، dil، lêv، hîn، qaz، qul، çak و şaş ـە؛ وشەیەک دەتوانێت لە وشەنامەدا واتای زیاتر هەبێت.</p></section>
<section class="klesson-card"><h2>٣. ڕاهێنانی خوێندنەوە و نوسین</h2><ol><li>وشەکانی <em>av، dil، lêv، hîn</em> و <em>qaz</em> بە پیتی گەورە و بچووک بنووسە، پاشان لەگەڵ سەرچاوەکە بەراوردیان بکە.</li><li>لە <em>çak</em> و <em>şaş</em> پیتی نیشانەدار دیاری بکە و بڵێ بۆچی نابێت نیشانەکە لاببرێت.</li><li>جیاوازیی نووسینی <em>i/î</em> و <em>u/û</em> لە <em>dil/hîn</em> و <em>qul/bûz</em> بەراورد بکە.</li><li>بە بێ گۆڕینی ڕێنووسی لاتینی، واتای هەر وشەیەک لە سەرچاوەدا بپشکنە.</li><li>بە دەنگی بەرز وشەکان بخوێنەوە؛ ئەگەر بەردەست بوو، گوێ لە تۆماری دەنگیی وشەنامەکە بگرە و وەک ڕێنمایی بەکاری بهێنە، نەک وەک جێگرەوەی قسەکەری زمان.</li></ol></section>
<section class="klesson-card"><h2>٤. خۆهەڵسەنگاندن</h2><ul><li>دەتوانم پیتەکانی وشەیەک بە ڕیز بناسم و نیشانە تایبەتەکان بپارێزم.</li><li>دەتوانم نیشانەکانی IPA لە پیتەکانی ئەلفبێ جیا بکەمەوە.</li><li>دەتوانم واتای وشە بە سەرچاوە پشتڕاست بکەمەوە، نەک بە گومان.</li><li>دەتوانم ڕێنووسی ستاندارد لە جیاوازیی دەنگیی شێوەزار جیا بکەمەوە.</li></ul></section>
<section class="klesson-card"><h2>سەرچاوەکان</h2><ol><li>University of Arizona, Iranian Languages. <a href="https://iranian-languages.arizona.edu/node/7" target="_blank" rel="noopener">Kurmanji Kurdish — Phonology and Orthography</a> (خشتەی ڤاوڵ و کۆنسۆنەنت و نمونە وشەکان).</li><li>Yari. <a href="https://yari.krd/dictionary/" target="_blank" rel="noopener">Kurmanji–English word list</a> (وشەنامە و تۆماری دەنگیی ڕێنمایی).</li><li>Thackston, W. M. (2006). <em>Kurmanji Kurdish: A Reference Grammar with Selected Readings</em>. Harvard University.</li></ol></section>',now()),
    ('kurmanji-course-1-lesson-10.html','kurmanji-course-1','دەربڕینە سەرەتاییەکان','<section class="klesson-card"><h2>١. سڵاو و ماڵئاوایی</h2><table class="klesson-table"><thead><tr><th>دەربڕینی کورمانجی</th><th>واتا بە کوردی</th><th>کات و بەکارهێنان</th></tr></thead><tbody>
<tr><td>Silav!</td><td>سڵاو!</td><td>سڵاوکردنی گشتی.</td></tr>
<tr><td>Rojbaş!</td><td>بەیانیت باش / ڕۆژباش!</td><td>سڵاوێکی باو لە کاتی ڕۆژدا.</td></tr>
<tr><td>Êvarbaş!</td><td>ئێوارە باش!</td><td>سڵاوێک بۆ کاتی ئێوارە.</td></tr>
<tr><td>Şevbaş!</td><td>شەوت باش!</td><td>بۆ ماڵئاوایی، بە تایبەتی لە شەو یان کاتی خەوتندا.</td></tr>
<tr><td>Bi xatirê te!</td><td>خواحافیز / ماڵئاوایی!</td><td>ماڵئاوایی؛ بەکارهێنان دەتوانێت بە کۆنتێکست بگۆڕێت.</td></tr>
<tr><td>Bi xêr hatî!</td><td>بەخێر بێیت!</td><td>بەخێرهاتن بۆ تاک؛ شێوەکە بەپێی ژمارە و ڕەگەز دەتوانێت بگۆڕێت.</td></tr>
</tbody></table><p class="klesson-note">دەربڕینەکان لە شێوەزار و بارودۆخی کۆمەڵایەتیی جیاوازدا هەندێک جیاوازییان هەیە. لە گفتوگۆی فەرمی و نافەرمی‌دا، کۆنتێکست و شێوەی بەکارهێنان لەبەرچاو بگرە.</p></section>
<section class="klesson-card"><h2>٢. ناساندن و پرسیارکردن لە بارودۆخ</h2><table class="klesson-table"><thead><tr><th>کورمانجی</th><th>واتا</th></tr></thead><tbody>
<tr><td>Tu çawa yî?</td><td>چۆنی؟ (بۆ تاک)</td></tr>
<tr><td>Ez baş im.</td><td>من باشم.</td></tr>
<tr><td>Navê min Azad e.</td><td>ناوی من ئازادە.</td></tr>
<tr><td>Tu kî yî?</td><td>تۆ کێیت؟</td></tr>
<tr><td>Ez ji ... me.</td><td>من خەڵکی ...م / لە ...م.</td></tr>
</tbody></table><p>لە نمونەی <em>Ez ji ... me</em> شوێنەکە بە ناوی گونجاو پڕ بکەرەوە. لە ڕستەی <em>Tu çawa yî?</em>، جێناوی <em>tu</em> بۆ تاکە؛ شێوەی بانگکردنی کۆ لە وانەکانی دواتردا دەخوێندرێتەوە.</p></section>
<section class="klesson-card"><h2>٣. سوپاس و داواکردنی یارمەتی</h2><table class="klesson-table"><thead><tr><th>کورمانجی</th><th>واتا</th><th>تێبینی</th></tr></thead><tbody>
<tr><td>Spas!</td><td>سوپاس!</td><td>دەربڕینی سوپاسگوزاری.</td></tr>
<tr><td>Ji kerema xwe.</td><td>تکایە.</td><td>داواکردنی ڕێزدارانە.</td></tr>
<tr><td>Erê.</td><td>بەڵێ.</td><td>وەڵامی ئەرێنی.</td></tr>
<tr><td>Na.</td><td>نەخێر.</td><td>وەڵامی نەرێنی.</td></tr>
<tr><td>Biborîne.</td><td>ببورە.</td><td>داوای لێبوردن؛ شێوە و ڕێنووس دەتوانێت لە سەرچاوەکاندا جیاواز بێت.</td></tr>
</tbody></table></section>
<section class="klesson-card"><h2>٤. گفتوگۆی کورت</h2><p><strong>A:</strong> Silav! Tu çawa yî?</p><p><strong>B:</strong> Silav! Ez baş im, spas. Tu çawa yî?</p><p><strong>A:</strong> Ez jî baş im.</p><p class="klesson-note">واتا: A سڵاو دەکات و دەپرسێت چۆنە. B وەڵام دەدات و سوپاس دەکات، پاشان پرسیارەکە دەگەڕێنێتەوە. وشەی <em>jî</em> لێرەدا واتای «هەروەها/هەروەها من» دەگەیەنێت.</p></section>
<section class="klesson-card"><h2>٥. ڕاهێنان</h2><ol><li>بە کورمانجی سڵاو بکە و بپرسە کەسەکە چۆنە.</li><li>بە ڕستەیەکی سادە خۆت بناسێنە: <em>Navê min ... e.</em></li><li>بۆ «سوپاس»، «تکایە» و «بەڵێ» هاوتای کورمانجی بنووسە.</li><li>گفتوگۆی دوو کەسییەک دروست بکە کە تێیدا سڵاو، پرسیار لە بارودۆخ و سوپاس هەبێت.</li><li>دەربڕینێک هەڵبژێرە و لە دوو سەرچاوەدا شێوەی نوسین و واتاکەی بەراورد بکە.</li></ol></section>
<section class="klesson-card"><h2>٦. سەرچاوەکان</h2><ol><li>Yari. <a href="https://yari.krd/learn/kurdish-greetings/" target="_blank" rel="noopener">Kurdish greetings and everyday phrases</a>.</li><li>Yari. <a href="https://yari.krd/dictionary/" target="_blank" rel="noopener">Kurmanji–English dictionary</a>.</li><li>W. M. Thackston. <em>Kurmanji Kurdish: A Reference Grammar with Selected Readings.</em> <a href="https://sites.fas.harvard.edu/~iranian/Kurmanji/kurmanji_complete.pdf" target="_blank" rel="noopener">PDF</a>.</li></ol></section>',now()),
    ('kurmanji-course-1-lesson-25.html','kurmanji-course-1','حاڵەتی ڕاستەوخۆ و ناڕاستەوخۆ','<section class="klesson-card"><h2>١. حاڵەت چیە؟</h2><p>حاڵەتی ڕێزمانی شێوەیەکە کە پەیوەندیی ناو یان جێناو بە ڕۆڵی لە ڕستەدا پیشان دەدات. لە کورمانجیدا جیاوازیی نێوان حاڵەتی ڕاستەوخۆ (<em>direct</em>) و ناڕاستەوخۆ (<em>oblique</em>) گرنگە؛ بە تایبەتی لە جێناوەکان، بەرکاری کردارە تێپەڕەکانی ئێستا، دوای ئامرازی پەیوەندی، خاوەنداری و ڕستەی ڕابردووی تێپەڕدا.</p><p class="klesson-note">ناوی «ڕاستەوخۆ/ناڕاستەوخۆ» لێرە ناوی دوو حاڵەتی ڕێزمانیی کورمانجییە، نەک تەنیا مانای ئاساییی وشەکانی «ڕاستەوخۆ» و «ناڕاستەوخۆ».</p></section>
<section class="klesson-card"><h2>٢. گۆڕانی ناو بە پێی حاڵەت</h2><p>فۆڕمی حاڵەتی ناو بە پێی ڕەگەزی ڕێزمانی، ژمارە و نیشانەی نەناسراوی دەگۆڕێت. لە نمونەی ستانداردی خوارەوەدا، ناوی نێری تاک زۆرجار لە حاڵەتی ڕاستەوخۆدا بێ کۆتاییی دیارە، بەڵام ناوی مێ و ناوی نەناسراو دەتوانن کۆتاییی دیار هەبێت.</p><table class="klesson-table"><thead><tr><th>ڕاستەوخۆ</th><th>ناڕاستەوخۆ</th><th>واتا</th></tr></thead><tbody><tr><td>gund</td><td>gund-î</td><td>گوند (نێری تاک، ناسراو)</td></tr><tr><td>gund-ek</td><td>gund-ek-î</td><td>گوندێک (نێری تاک، نەناسراو)</td></tr><tr><td>jin</td><td>jin-ê</td><td>ژن (مێی تاک، ناسراو)</td></tr><tr><td>jin-ek</td><td>jin-ek-ê</td><td>ژنێک (مێی تاک، نەناسراو)</td></tr></tbody></table><p class="klesson-note">خشتەی سەرەوە نمونەی ڕێزمانی ستانداردە و لەسەر فۆڕمەکانی <em>gund</em> و <em>jin</em> دامەزراوە. لە هەندێک شێوەزاردا، بە تایبەتی لە ناوی نێری تاکی بەڕووت، نیشانەی حاڵەتی ناڕاستەوخۆ دەکرێت لە ڕووی دەرەوەدا نەردەکەوێت؛ بەڵام لەگەڵ نیشانەی نەناسراوی <em>-ek</em>، نیشانەکە بە شێوەیەکی ڕونتر دەردەکەوێت. بۆیە <em>mirov</em> و <em>mirov-ek</em> لەم خشتەیەدا وەک هاوتای فۆڕمە ستانداردەکانی خشتەی سەرەکی نیشان نەدراون. جیاوازیی شێوەزارەکان دەبێت بە سەرچاوەی دیاریکراوەوە پشکنین بکرێت.</p></section>
<section class="klesson-card"><h2>٣. جێناوە ڕاستەوخۆ و ناڕاستەوخۆکان</h2><p>جێناوە سەربەخۆکانیش دوو کۆمەڵە فۆڕمیان هەیە. فۆڕمی ڕاستەوخۆی ew بۆ تاکی نێر، تاکی مێ و کۆ بەکاردێت؛ واتە ژمارە و ڕەگەز هەمیشە لە خودی ئەم فۆڕمەوە دیار نابن و سیاق یارمەتی دەدات. بە پێچەوانەوە، لە فۆڕمی ناڕاستەوخۆدا لە تاکدا wî بۆ نێر و wê بۆ مێ بەکاردێت، بەڵام فۆڕمی کۆ wan ـە. لە ڕستەی ئێستادا، جێناوی ڕاستەوخۆ زۆرجار بکەرە؛ فۆڕمی ناڕاستەوخۆ لە بەرکار، دوای ئامرازی پەیوەندی و لە دەربڕینی خاوەنداریدا دەردەکەوێت. لە ڕابردووی کردارە تێپەڕەکاندا، ئەم دابەشبوونە گرنگترە و پەیوەندی بە سیستەمی ئەرجەتیڤی کورمانجییەوە هەیە.</p><table class="klesson-table"><thead><tr><th>ڕاستەوخۆ</th><th>ناڕاستەوخۆ</th><th>کەس</th></tr></thead><tbody><tr><td>ez</td><td>min</td><td>من</td></tr><tr><td>tu</td><td>te</td><td>تۆ</td></tr><tr><td>ew</td><td>wî / wê</td><td>ئەو (لە تاکدا wî بۆ نێر و wê بۆ مێ؛ لە کۆدا wan)</td></tr><tr><td>em</td><td>me</td><td>ئێمە</td></tr><tr><td>hûn</td><td>we</td><td>ئێوە</td></tr><tr><td>ew</td><td>wan</td><td>ئەوان</td></tr></tbody></table></section>
<section class="klesson-card"><h2>٤. حاڵەت لە ڕستەی ئێستا و ڕابردوودا</h2><p>لە ڕستەی ئێستای تێپەڕدا، بکەر زۆرجار لە حاڵەتی ڕاستەوخۆ و بەرکار لە ناڕاستەوخۆدا دێت:</p><p><strong>Ez wî mirovî dibînim.</strong><br>من ئەو پیاوە دەبینم.</p><p class="klesson-note">شیکردنەوە: <em>ez</em> بکەری ڕاستەوخۆیە؛ <em>wî</em> و <em>mirovî</em> لەم ڕستەیەدا فۆڕمی ناڕاستەوخۆن. لە ڕستەی ئێستای تێپەڕدا کردار لەگەڵ بکەر ڕێکدەکەوێت.</p><p>لە ڕستەی ڕابردووی تێپەڕدا، کورمانجی ڕێکخستنی ئەرجەتیڤی بەکاردەهێنێت: بکەری ڕێزمانی زۆرجار لە حاڵەتی ناڕاستەوخۆیە و بەرکار لە حاڵەتی ڕاستەوخۆدا دێت.</p><p><strong>Min ew dît.</strong><br>من ئەوم بینی.</p><p class="klesson-note">شیکردنەوە: <em>min</em> بکەری ناڕاستەوخۆیە؛ <em>ew</em> بەرکاری ڕاستەوخۆیە. <em>dît</em> کردارەکەی ڕابردووی تێپەڕە و لە ئەم نمونەیەدا لەگەڵ بەرکاری تاک ڕێکدەکەوێت.</p><p class="klesson-note">ئەم نموونانە بنەڕەتیین. لە ڕستەی ڕابردووی تێپەڕدا، لە ڕێکخستنی ئەرجەتیڤی بنەڕەتیدا کردار لەگەڵ بەرکار ڕێکدەکەوێت، نەک لەگەڵ بکەر. بەڵام لە کورمانجیدا ڕێککەوتنی کردار و حاڵەتی بەرکار لە هەندێک شێوەزار و سیاقی تایبەتدا جیاوازییان هەیە؛ بۆیە ئەم یاسایە وەک بنەمای گشتی فێر دەکرێت، نەک وەک یاسایەکی بێ‌هەڵوێست بۆ هەمو نمونەکان.</p></section>
<section class="klesson-card"><h2>٥. ڕاهێنان</h2><ol><li>جیاوازیی نێوان <em>gund</em> و <em>gund-î</em> لە ڕووی حاڵەتی ڕێزمانی ڕون بکەوە.</li><li>فۆڕمە ڕاستەوخۆ و ناڕاستەوخۆکانی <em>ez/min</em> و <em>tu/te</em> لەبەر بکە.</li><li>لە ڕستەی <em>Ez wî mirovî dibînim</em> بکەر و بەرکار دیاری بکە.</li><li>لە ڕستەی <em>Min ew dît</em> ڕۆڵی <em>min</em> و <em>ew</em> باس بکە.</li><li>بە وشەی خۆت ڕون بکەوە بۆچی ڕابردووی کردارە تێپەڕەکان لە کورمانجیدا سیستەمی جیاوازی حاڵەت هەیە.</li></ol></section>
<section class="klesson-card"><h2>٦. سەرچاوەکان</h2><ol><li>Geoffrey Haig (2018), <a href="https://doi.org/10.1515/9783110421682-004" target="_blank" rel="noopener"><em>Northern Kurdish (Kurmanjî)</em></a>, in Geoffrey Haig &amp; Geoffrey Khan (eds.), <em>The Languages and Linguistics of Western Asia: An Areal Perspective</em>, pp. 106–158, Table 7 and sections on case and ergativity.</li><li>University of Arizona, <a href="https://iranian-languages.arizona.edu/node/7" target="_blank" rel="noopener">Kurmanji Kurdish</a>, noun case, pronouns and past tense.</li><li>Thackston, W. M., <a href="https://sites.fas.harvard.edu/~iranian/Kurmanji/kurmanji_complete.pdf" target="_blank" rel="noopener"><em>Kurmanji Kurdish: A Reference Grammar with Selected Readings</em></a>.</li></ol></section>',now()),
    ('kurmanji-course-2-lesson-04.html','kurmanji-course-2','ناوی دیار و نادیار؛ پاشگری -ek','<section class="klesson-card"><h2>١. نادیاری بە -ek</h2><p>لە نمونەی باوی کورمانجی‌دا gund ‘گوند’ و gundek ‘گوندێک’ بەراورد دەکرێن. -ek نیشانەی نادیاریی تاکە؛ لە شیکردنەوەی ورددا پەیویستە فۆڕمی حاڵەتی ڕاستەوخۆ/ناڕاستەوخۆ و ئەزافەش لەبەرچاو بگیرێت.</p></section><section class="klesson-card"><h2>٢. ناوی بێ پاشگر</h2><p>ناوی بێ -ek هەمیشە بە واتای دیار نیە؛ بە پێی سیاق دەتوانێت ئاماژە بە شتێکی ناسراو، جۆرێک بە گشتی، یان شتێک کە لە گفتوگۆدا دیارە بکات. بۆیە پەیویستە ڕستە و سیاق بخوێندرێتەوە.</p></section><section class="klesson-card"><h2>٣. حاڵەت و فۆڕمی نادیار</h2><p>لە ستانداردی کورمانجی‌دا شێوەی ناوی نادیار دەتوانێت لە حاڵەتی ناڕاستەوخۆدا نیشانەی زیاتر وەربگرێت؛ وەک <em>gund-ek-î</em> و <em>jin-ek-ê</em>. لەم فۆڕمانەدا <em>-ek</em> نیشانەی نادیاریی تاکە، و کۆتاییی <em>-î/-ê</em> فۆڕمی حاڵەتی ناڕاستەوخۆی ناوەکە نیشان دەدات. ئەمە لە نمونەی <em>bajar-ek-î mezin</em> جیاوازە: لەو پێکهاتەیەدا <em>-î</em> پەیوەندیی ئەزافە دروست دەکات بۆ بەستنەوەی هاوەڵناوی <em>mezin</em> بە ناوەکە. واتە فۆڕمی ڕووکەشی هاوشێوە هەمیشە ئەرکی ڕێزمانیی یەکسان نیە؛ پەیویستە پێکهاتە و سیاق بپشکنرێت.</p></section>
<section class="klesson-card"><h2>تێبینیی مێتۆدی</h2><p class="klesson-note">Haig (2018)، لە بەشی ناوی کورمانجی و خشتەی حاڵەت، جیاوازی حاڵەتی ڕاستەوخۆ/ناڕاستەوخۆ و فۆڕمی ناوی نادیار پیشان دەدات. شێوەی هەر ناوێک بە ڕەگەز، حاڵەت و سیاقەوە پەیوەستە.</p></section>
<section class="klesson-card"><h2>پرسیارەکانی پێداچوونەوە</h2><ol><li>پاشگری -ek زۆرجار چی نیشان دەدات؟</li><li>بۆچی ناوی بێ -ek هەمیشە دیار نیە؟</li><li>چۆن حاڵەت دەتوانێت فۆڕمی ناوی نادیار بگۆڕێت؟</li></ol></section>
<section class="klesson-card"><h2>سەرچاوەکان</h2><ul><li>Haig, Geoffrey. (2018). “Northern Kurdish (Kurmanjî).” In Geoffrey Haig & Geoffrey Khan (eds.), <em>The Languages and Linguistics of Western Asia: An Areal Perspective</em>, pp. 106–158. Berlin: De Gruyter Mouton. <a href="https://doi.org/10.1515/9783110421682-004" target="_blank" rel="noopener">DOI: 10.1515/9783110421682-004</a>.</li><li>Thackston, W. M. (2006). <em>Kurmanji Kurdish: A Reference Grammar with Selected Readings.</em> Renas Media. <a href="https://kurdishacademy.org/?page_id=623" target="_blank" rel="noopener">پەڕەی کتێب لە ئەکادێمیای کوردی</a>.</li></ul><p class="klesson-note">نمونە و یاساکان لە چوارچێوەی کورمانجیی ستاندارددا پێشکەش کراون؛ بۆ جیاوازیی شێوەزار و فۆڕمی تایبەت، دەبێت سەرچاوە و سیاق دیاری بکرێن.</p></section>',now()),
    ('kurmanji-course-2-lesson-06.html','kurmanji-course-2','خاوەنداری و جێناوە خاوەندارییەکان','<section class="klesson-card"><h2>١. خاوەندار بە ئەزافە</h2><p>پێکهاتەی ئەزافە دەتوانێت پەیوەندیی خاوەنداری نیشان بدات. لە نمونەی Haig (2018)، <em>mal-a me</em> ‘ماڵی ئێمە’، <em>-a</em> پەیوەندیی ئەزافەی نێوان ناو و جێناوی خاوەندار دروست دەکات؛ <em>me</em> فۆڕمی ناڕاستەوخۆی جێناوی کەسیی <em>em</em> ـە و لێرەدا وەک خاوەندار بەکاردێت. بۆیە نابێت <em>-a</em> بە نیشانەی خاوەنداریی سەربەخۆ یان <em>me</em> بە فۆڕمی ڕاستەوخۆ تێبگەین. فۆڕمی ئەزافە لەگەڵ ناوی سەرەکی پەیوەستە.</p></section><section class="klesson-card"><h2>٢. جێناوی خاوەنداری</h2><p>جێناوە خاوەندارییەکان لە سیاقە جیاوازەکاندا بەکاردێن و فۆڕمیان بە پێی کەس و ژمارە دەگۆڕێت. پەیویستە جێناوی کەسیی سەربەخۆ لە فۆڕمی خاوەنداری و لە جێناوی ناو ڕستە جیا بکرێتەوە.</p></section><section class="klesson-card"><h2>٣. جێناوی خۆ (xwe)</h2><p><em>xwe</em> جێناوێکی خۆگەڕە و لە فۆڕمەکەیدا بە پێی کەس و ژمارە ناگۆڕێت. ئەگەر خاوەندار لە هەمان ڕستەدا بگەڕێتەوە بۆ بکەر، لە کورمانجیی ستاندارددا <em>xwe</em> بەکاربهێنە، نەک جێناوی کەسیی ناڕاستەوخۆی <em>min</em>. بۆ نمونە: <em>Ez li mal-a xwe me.</em> «من لە ماڵی خۆمم». لەم سیاقەدا <em>mal-a min</em> وەک خاوەنداریی هاوئاماژەی هەمان ڕستە ڕاست نیە. بەڵام ئەگەر خاوەندار بۆ کەسێکی دیکە بگەڕێتەوە، پەیویستە ئاماژەی ڕستەی تەواو بپشکنرێت.</p></section>
<section class="klesson-card"><h2>تێبینیی مێتۆدی</h2><p class="klesson-note">نمونەی <em>mal-a me</em> لە Haig (2018)، §2.3.1، نمونەی (5) هاتووە؛ لێکدانەوەی <em>xwe</em> وەک جێناوی خۆگەڕ لە §2.2.3 (Pronouns) هاتووە. لە ستانداردی کورمانجی‌دا <em>xwe</em> بۆ خاوەنداریی هاوئاماژە بە بکەری هەمان ڕستە بەکاردێت؛ جیاوازیی شێوەزار، بە تایبەتی کورمانجیی ڕۆژئاوا، دەبێت جیاواز بپشکنرێت. سەرچاوە: <a href="https://doi.org/10.1515/9783110421682-004" target="_blank" rel="noopener">Haig (2018)</a>.</p></section>
<section class="klesson-card"><h2>پرسیارەکانی پێداچوونەوە</h2><ol><li>ئەزافە چۆن خاوەنداری دەردەبڕێت؟</li><li>جیاوازی جێناوی کەسی و خاوەنداری چیە؟</li><li>xwe لە چ جۆر سیاقێکدا بەکاردێت؟</li></ol></section>
<section class="klesson-card"><h2>سەرچاوەکان</h2><ul><li>Haig, Geoffrey. (2018). “Northern Kurdish (Kurmanjî).” In Geoffrey Haig & Geoffrey Khan (eds.), <em>The Languages and Linguistics of Western Asia: An Areal Perspective</em>, pp. 106–158. Berlin: De Gruyter Mouton. <a href="https://doi.org/10.1515/9783110421682-004" target="_blank" rel="noopener">DOI: 10.1515/9783110421682-004</a>.</li><li>Thackston, W. M. (2006). <em>Kurmanji Kurdish: A Reference Grammar with Selected Readings.</em> Renas Media. <a href="https://kurdishacademy.org/?page_id=623" target="_blank" rel="noopener">پەڕەی کتێب لە ئەکادێمیای کوردی</a>.</li></ul><p class="klesson-note">نمونە و یاساکان لە چوارچێوەی کورمانجیی ستاندارددا پێشکەش کراون؛ بۆ جیاوازیی شێوەزار و فۆڕمی تایبەت، دەبێت سەرچاوە و سیاق دیاری بکرێن.</p></section>',now()),
    ('kurmanji-course-2-lesson-09.html','kurmanji-course-2','کاتی ئێستا، ڕابردوو و داهاتوو','<section class="klesson-card"><h2>١. کاتی ئێستا</h2><p>لە کاتی ئێستادا، پێشگر و فۆڕمی کردار دەتوانن زانیاریی کات و ڕەوش بگەیەنن. بۆ نمونە، فۆڕمەکانی di- لە زۆر کردارەکاندا لە پێکهاتەی ئێستادا دەردەکەون؛ بەڵام کردارە تایبەتەکان فۆڕمی جیاوازیان هەیە.</p></section><section class="klesson-card"><h2>٢. کاتی ڕابردوو</h2><p>ڕابردوو یەک شێوەی سادە نیە: جیاوازی نێوان کردارە تێپەڕ و ناتێپەڕەکان و فۆڕمەکانی کردار لە ڕێکخستنی ڕستەدا کاریگەری هەیە. لە ڕستەی ڕابردووی کردارە تێپەڕەکاندا سیستەمی حاڵەت گرنگە.</p></section><section class="klesson-card"><h2>٣. داهاتوو و واتای کات</h2><p>واتای داهاتوو دەتوانێت بە پێکهاتەی کردار و وشەی یاریدەدەر دەرببڕدرێت؛ شێوەی بەکارهێنان بە سیاق و جۆری ڕستەوە پەیوەستە. لە شیکردنەوەدا فۆڕمی کردار لەگەڵ نیشانەکانی کات و سیاق بە یەکەوە بخوێنەوە.</p></section>
<section class="klesson-card"><h2>٤. بەراوردی فۆڕمەکانی کردار</h2><p>لە نمونەکانی Haig (2018)، خشتەی ١٤، <code>ez dibêjim</code> فۆڕمی ئێستایە؛ <code>ez hatim</code> ڕابردووی کرداری ناتێپەڕە؛ <code>min xwar</code> ڕابردووی کرداری تێپەڕە. لە ڕستەی ڕابردووی تێپەڕدا، فۆڕمی جێناو و ڕێککەوتنی کردار لەگەڵ ئەوەی لە ڕستەی ئێستادا دەبینرێت جیاوازە.</p><p>بۆ جیاکردنەوەی ڕابردووی سادە لە ڕابردووی بەردەوام/ناکامڵ، سەرچاوە ئەم بەراوردەش دەدات: <code>ez hatim</code> (ڕابردووی سادەی ناتێپەڕ) لە بەرابەر <code>ez dihatim</code> (ڕابردووی بەردەوامی ناتێپەڕ)، هەروەها <code>min xwar</code> لە بەرابەر <code>min dixwar</code>.</p><p>بۆ داهاتوو، Haig (§2.6.4) نمونەی <code>ew dē mesel-ē ji te re bēž-e</code> دەهێنێتەوە: «ئەو کێشەکە بۆ تۆ دەڵێت». لەو نمونەیەدا <code>dē</code> نیشانەی داهاتووە و کردارەکە فۆڕمی subjunctive ـە. ئەم نوسینەی لاتینیە بە شێوەی سەرچاوە پارێزراوە؛ فۆڕمی نوێی دروستکراو نیە.</p></section>
<section class="klesson-card"><h2>تێبینیی مێتۆدی</h2><p class="klesson-note">ئەم وانەیە پێشەکییە بۆ سیستەمی کات و ڕەوش. خشتەی پارادایمی تەواو پەیویستی بە سەرچاوەی تایبەت و دیاریکردنی شێوەزار هەیە؛ لێرەدا فۆڕمی ناپشکنراو دروست نەکراوە.</p></section>
<section class="klesson-card"><h2>پرسیارەکانی پێداچوونەوە</h2><ol><li>پێشگری di- لە زۆر کردارەکانی کاتی ئێستادا چ ڕۆڵێکی هەیە؟</li><li>بۆچی ڕابردووی کردارە تێپەڕەکان بە جیاوازی لە کردارە ناتێپەڕەکان دەخوێندرێتەوە؟</li><li>داهاتوو بۆچی نابێت بە یاسای پاشگری یەکسان کورت بکرێتەوە؟</li></ol></section>
<section class="klesson-card"><h2>سەرچاوەکان</h2><ul><li>Haig, Geoffrey. (2018). “Northern Kurdish (Kurmanjî).” In Geoffrey Haig & Geoffrey Khan (eds.), <em>The Languages and Linguistics of Western Asia: An Areal Perspective</em>, pp. 106–158. Berlin: De Gruyter Mouton. <a href="https://doi.org/10.1515/9783110421682-004" target="_blank" rel="noopener">DOI: 10.1515/9783110421682-004</a>.</li><li>Thackston, W. M. (2006). <em>Kurmanji Kurdish: A Reference Grammar with Selected Readings.</em> Renas Media. <a href="https://kurdishacademy.org/?page_id=623" target="_blank" rel="noopener">پەڕەی کتێب لە ئەکادێمیای کوردی</a>.</li></ul><p class="klesson-note">نمونە و یاساکان لە چوارچێوەی کورمانجیی ستاندارددا پێشکەش کراون؛ بۆ جیاوازیی شێوەزار و فۆڕمی تایبەت، دەبێت سەرچاوە و سیاق دیاری بکرێن.</p></section>',now()),
    ('kurmanji-course-2-lesson-10.html','kurmanji-course-2','ڕستەی نەفی و پرسیاری','<section class="klesson-card"><h2>١. نەفیی کردار</h2><p>لە زۆر فۆڕمەکانی کاتی ئێستای کورمانجی‌دا، na- بۆ نەفی بەکاردێت و لە بەرابەر di- دێت؛ بەڵام کردارە تایبەتەکان هەن، بۆیە یاساکە نابێت بەبێ پشکنین بۆ هەمو کردارەکان بگشتێندرێت.</p></section><section class="klesson-card"><h2>٢. نەفیی ڕستەی ناوەکی</h2><p>نەفیی ڕستەی ناوەکی و نەفیی کردار هەمیشە بە هەمان فۆڕم دروست نابن. فۆڕمی نەفی دەبێت بە پێی جۆری پێکهاتە و کردار بپشکنرێت.</p></section><section class="klesson-card"><h2>٣. پرسیاری بەڵێ/نەخێر و وشە پرسیاری</h2><p>پرسیاری بەڵێ/نەخێر دەتوانێت بە ئاواز و سیاق ناسرێتەوە؛ پرسیاری زانیاریییش وشەی پرسیاری وەک کێ، چی، لە کوێ یان کەی بەکار دەهێنێت. ڕیزبەندی وشەکان لە ڕستەی پرسیاریدا دەبێت بە پێی شێوەی ستاندارد و سیاق بپشکنرێت.</p></section>
<section class="klesson-card"><h2>٤. نمونەی نەفی لە سەرچاوەی زانستی</h2><p>Haig (2018)، لە بەشی پێشگری نەفی، دەڵێت <code>na-</code> لە زۆر فۆڕمەکانی ئێستادا جێگای <code>di-</code> دەگرێتەوە؛ بەڵام ئەمە یاسایەکی بێ‌استثنا نیە. بۆ دوو کردارەکەی <code>zanîn</code> «زانین» و <code>karîn</code> «توانین»، نمونەکانی <code>nizanim</code> «نازانم» و <code>nikarim</code> «ناتوانم» هاتوون.</p><p>لە ڕابردوودا، سەرچاوە ئەم بەراوردە دەدات: <code>ne-hatin</code> «نەهاتن» و <code>ne-di-hatin</code> «نەدەهاتن/لە هاتندا نەبوون». لێرەدا <code>ne-</code> لەگەڵ فۆڕمی ڕابردووی سادە یان بەردەوام بەکاردێت. شێوە و واتای ورد دەبێت لەگەڵ کات، جۆری کردار و شێوەزار بخوێندرێتەوە.</p><p class="klesson-note">ئەم فۆڕمانە وەک نوسینی لاتینیی سەرچاوە پارێزراون؛ لە نمونەی تاکەوە یاسای گشتی بۆ هەمو کردارەکان مەدەرهێنە.</p></section>
<section class="klesson-card"><h2>تێبینیی مێتۆدی</h2><p class="klesson-note">فۆڕمەکانی نەفی و پرسیار لە کردارە جیاوازەکاندا بەراورد بکە؛ یاسایەکی گشتی لە نمونەی تاکەوە مەدەرهێنە.</p></section>
<section class="klesson-card"><h2>پرسیارەکانی پێداچوونەوە</h2><ol><li>na- لە زۆر فۆڕمەکانی کاتی ئێستادا چی دەکات؟</li><li>جیاوازی نەفیی کردار و ڕستەی ناوەکی چیە؟</li><li>دوو جۆری پرسیاری سەرەکی چین؟</li></ol></section>
<section class="klesson-card"><h2>سەرچاوەکان</h2><ul><li>Haig, Geoffrey. (2018). “Northern Kurdish (Kurmanjî).” In Geoffrey Haig & Geoffrey Khan (eds.), <em>The Languages and Linguistics of Western Asia: An Areal Perspective</em>, pp. 106–158. Berlin: De Gruyter Mouton. <a href="https://doi.org/10.1515/9783110421682-004" target="_blank" rel="noopener">DOI: 10.1515/9783110421682-004</a>.</li><li>Thackston, W. M. (2006). <em>Kurmanji Kurdish: A Reference Grammar with Selected Readings.</em> Renas Media. <a href="https://kurdishacademy.org/?page_id=623" target="_blank" rel="noopener">پەڕەی کتێب لە ئەکادێمیای کوردی</a>.</li></ul><p class="klesson-note">نمونە و یاساکان لە چوارچێوەی کورمانجیی ستاندارددا پێشکەش کراون؛ بۆ جیاوازیی شێوەزار و فۆڕمی تایبەت، دەبێت سەرچاوە و سیاق دیاری بکرێن.</p></section>',now())
    ON CONFLICT (lesson_key) DO UPDATE
      SET title = EXCLUDED.title,
          content_html = EXCLUDED.content_html,
          updated_at = now()
      WHERE public.lesson_content.course_id = EXCLUDED.course_id
    RETURNING lesson_key
  )
  SELECT count(*) INTO affected_rows FROM changed;

  IF affected_rows <> 12 THEN
    RAISE EXCEPTION USING
      ERRCODE = '55000',
      MESSAGE = format(
        'Kurmanji content reconciliation aborted: expected 12 updated rows, changed %s.',
        affected_rows
      );
  END IF;
END;
$apply$;

COMMIT;
